package subscription

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Plan defines a recurring billing tier that a provider offers.
type Plan struct {
	ID            int64
	Provider      address
	Name          string
	PricePerCycle int64
	CycleBlocks   int64
	Active        bool
}

// Sub tracks a subscriber's relationship to a plan.
type Sub struct {
	Subscriber   address
	PlanID       int64
	NextDueAt    int64
	Active       bool
}

var (
	plans   *avl.Tree // planID (string) -> *Plan
	subs    *avl.Tree // subscriber|planID (string) -> *Sub
	nextID  int64
)

func init() {
	plans = avl.NewTree()
	subs = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("subscription: must be a direct user call")
	}
	return cur.Previous().Address()
}

func planKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func subKey(subscriber address, planID int64) string {
	return string(subscriber) + "|" + planKey(planID)
}

func getPlan(id int64) *Plan {
	key := planKey(id)
	if !plans.Has(key) {
		panic("subscription: plan not found")
	}
	raw := plans.Get(key)
	return raw.(*Plan)
}

// CreatePlan lets a provider register a new subscription plan.
func CreatePlan(cur realm, name string, pricePerCycle int64, cycleBlocks int64) int64 {
	caller := assertUserCall(cur)
	if pricePerCycle <= 0 {
		panic("subscription: pricePerCycle must be positive")
	}
	if cycleBlocks <= 0 {
		panic("subscription: cycleBlocks must be positive")
	}
	if name == "" {
		panic("subscription: name required")
	}

	id := nextID
	nextID++

	plans.Set(planKey(id), &Plan{
		ID:            id,
		Provider:      caller,
		Name:          name,
		PricePerCycle: pricePerCycle,
		CycleBlocks:   cycleBlocks,
		Active:        true,
	})
	return id
}

// DeactivatePlan lets the provider stop offering a plan to new subscribers.
// Existing subscribers are unaffected.
func DeactivatePlan(cur realm, planID int64) {
	caller := assertUserCall(cur)
	p := getPlan(planID)
	if caller != p.Provider {
		panic("subscription: only the provider can deactivate")
	}
	p.Active = false
}

// Subscribe starts a subscription and pays the first cycle up front.
func Subscribe(cur realm, planID int64) {
	caller := assertUserCall(cur)
	p := getPlan(planID)
	if !p.Active {
		panic("subscription: plan is not active")
	}

	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount != p.PricePerCycle {
		panic("subscription: must send exact price per cycle")
	}

	key := subKey(caller, planID)
	if subs.Has(key) {
		existing := subs.Get(key).(*Sub)
		if existing.Active {
			panic("subscription: already subscribed to this plan")
		}
	}

	now := runtime.ChainHeight()
	subs.Set(key, &Sub{
		Subscriber: caller,
		PlanID:     planID,
		NextDueAt:  now + p.CycleBlocks,
		Active:     true,
	})

	// Forward payment to provider immediately.
	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(realmAddr, p.Provider, chain.Coins{chain.NewCoin("ugnot", amount)})
}

// RenewSubscription lets a subscriber pay for their next cycle once due.
func RenewSubscription(cur realm, planID int64) {
	caller := assertUserCall(cur)
	p := getPlan(planID)

	key := subKey(caller, planID)
	if !subs.Has(key) {
		panic("subscription: no subscription found")
	}
	s := subs.Get(key).(*Sub)
	if !s.Active {
		panic("subscription: subscription is not active")
	}

	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount != p.PricePerCycle {
		panic("subscription: must send exact price per cycle")
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(realmAddr, p.Provider, chain.Coins{chain.NewCoin("ugnot", amount)})

	s.NextDueAt = s.NextDueAt + p.CycleBlocks
}

// IsCurrent reports whether a subscriber's subscription is active and not overdue.
func IsCurrent(subscriber address, planID int64) bool {
	key := subKey(subscriber, planID)
	if !subs.Has(key) {
		return false
	}
	s := subs.Get(key).(*Sub)
	if !s.Active {
		return false
	}
	return runtime.ChainHeight() <= s.NextDueAt
}

// Cancel lets a subscriber end their subscription (no refund of the current cycle).
func Cancel(cur realm, planID int64) {
	caller := assertUserCall(cur)
	key := subKey(caller, planID)
	if !subs.Has(key) {
		panic("subscription: no subscription found")
	}
	s := subs.Get(key).(*Sub)
	s.Active = false
}

func Render(path string) string {
	out := "# Subscription Service\n\n"
	out += ufmt.Sprintf("Total plans: %d\n\n", plans.Size())
	plans.Iterate("", "", func(key string, value interface{}) bool {
		p := value.(*Plan)
		out += ufmt.Sprintf("## #%d: %s\n", p.ID, p.Name)
		out += ufmt.Sprintf("Price/cycle: %d ugnot | Cycle: %d blocks | Active: %t\n\n",
			p.PricePerCycle, p.CycleBlocks, p.Active)
		return false
	})
	return out
}

package ringbuffer

// Buffer is a fixed-capacity circular buffer of int64 values.
// When full, pushing a new value overwrites the oldest one.
type Buffer struct {
	data     []int64
	capacity int
	start    int // index of the oldest element
	size     int // number of elements currently stored
}

// New creates a new ring buffer with the given fixed capacity.
func New(capacity int) *Buffer {
	if capacity <= 0 {
		panic("ringbuffer: capacity must be positive")
	}
	return &Buffer{
		data:     make([]int64, capacity),
		capacity: capacity,
		start:    0,
		size:     0,
	}
}

// Push adds a value, overwriting the oldest entry if the buffer is full.
func (b *Buffer) Push(v int64) {
	writeIdx := (b.start + b.size) % b.capacity
	if b.size < b.capacity {
		b.data[writeIdx] = v
		b.size++
	} else {
		b.data[b.start] = v
		b.start = (b.start + 1) % b.capacity
	}
}

// Len returns the number of elements currently stored.
func (b *Buffer) Len() int {
	return b.size
}

// Capacity returns the maximum number of elements the buffer can hold.
func (b *Buffer) Capacity() int {
	return b.capacity
}

// At returns the element at logical index i (0 = oldest, Len()-1 = newest).
func (b *Buffer) At(i int) int64 {
	if i < 0 || i >= b.size {
		panic("ringbuffer: index out of range")
	}
	return b.data[(b.start+i)%b.capacity]
}

// Latest returns the most recently pushed value.
func (b *Buffer) Latest() int64 {
	if b.size == 0 {
		panic("ringbuffer: buffer is empty")
	}
	return b.At(b.size - 1)
}

// ToSlice returns a snapshot of all stored elements, oldest first.
func (b *Buffer) ToSlice() []int64 {
	out := make([]int64, b.size)
	for i := 0; i < b.size; i++ {
		out[i] = b.At(i)
	}
	return out
}

// Sum returns the sum of all stored elements.
func (b *Buffer) Sum() int64 {
	var total int64
	for i := 0; i < b.size; i++ {
		total += b.At(i)
	}
	return total
}

// Average returns the average of all stored elements. Panics if empty.
func (b *Buffer) Average() int64 {
	if b.size == 0 {
		panic("ringbuffer: buffer is empty")
	}
	return b.Sum() / int64(b.size)
}

package semver

// Version represents a parsed semantic version (major.minor.patch),
// optionally with a pre-release identifier (e.g. "1.2.3-beta").
type Version struct {
	Major      int64
	Minor      int64
	Patch      int64
	PreRelease string // empty means a normal release
}

// Parse parses a version string like "1.2.3" or "1.2.3-beta".
func Parse(s string) Version {
	if s == "" {
		panic("semver: empty version string")
	}

	core := s
	pre := ""
	for i := 0; i < len(s); i++ {
		if s[i] == '-' {
			core = s[:i]
			pre = s[i+1:]
			break
		}
	}

	parts := splitDot(core)
	if len(parts) != 3 {
		panic("semver: version must have exactly 3 dot-separated numeric parts")
	}

	return Version{
		Major:      parseUint(parts[0]),
		Minor:      parseUint(parts[1]),
		Patch:      parseUint(parts[2]),
		PreRelease: pre,
	}
}

func splitDot(s string) []string {
	parts := []string{}
	cur := ""
	for i := 0; i < len(s); i++ {
		if s[i] == '.' {
			parts = append(parts, cur)
			cur = ""
		} else {
			cur += string(s[i])
		}
	}
	parts = append(parts, cur)
	return parts
}

func parseUint(s string) int64 {
	if s == "" {
		panic("semver: empty numeric component")
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			panic("semver: invalid numeric component")
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

// Compare returns -1, 0, or 1 if v is less than, equal to, or greater than other.
// A version without a pre-release is considered greater than the same
// major.minor.patch with a pre-release (matches common semver convention).
func (v Version) Compare(other Version) int {
	if v.Major != other.Major {
		return cmpInt(v.Major, other.Major)
	}
	if v.Minor != other.Minor {
		return cmpInt(v.Minor, other.Minor)
	}
	if v.Patch != other.Patch {
		return cmpInt(v.Patch, other.Patch)
	}
	if v.PreRelease == other.PreRelease {
		return 0
	}
	if v.PreRelease == "" {
		return 1
	}
	if other.PreRelease == "" {
		return -1
	}
	if v.PreRelease < other.PreRelease {
		return -1
	}
	return 1
}

func cmpInt(a, b int64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// GreaterThan reports whether v is strictly greater than other.
func (v Version) GreaterThan(other Version) bool {
	return v.Compare(other) > 0
}

// LessThan reports whether v is strictly less than other.
func (v Version) LessThan(other Version) bool {
	return v.Compare(other) < 0
}

// Equal reports whether v and other are the same version.
func (v Version) Equal(other Version) bool {
	return v.Compare(other) == 0
}

// String renders the version back to its canonical string form.
func (v Version) String() string {
	s := itoa(v.Major) + "." + itoa(v.Minor) + "." + itoa(v.Patch)
	if v.PreRelease != "" {
		s += "-" + v.PreRelease
	}
	return s
}

func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

package bloomfilter

import (
	"crypto/sha256"
)

// Filter is a simple Bloom filter backed by a bit array, using k
// independent hash functions derived from a single sha256 digest.
type Filter struct {
	bits    []byte
	numBits int64
	k       int
}

// New creates a new Bloom filter with the given bit array size and number
// of hash functions.
func New(numBits int64, k int) *Filter {
	if numBits <= 0 {
		panic("bloomfilter: numBits must be positive")
	}
	if k <= 0 {
		panic("bloomfilter: k must be positive")
	}
	numBytes := (numBits + 7) / 8
	return &Filter{
		bits:    make([]byte, numBytes),
		numBits: numBits,
		k:       k,
	}
}

// hashes derives k independent hash values from the input using sha256
// with a counter as domain separator (simple double hashing scheme).
func (f *Filter) hashes(data []byte) []int64 {
	out := make([]int64, f.k)
	for i := 0; i < f.k; i++ {
		buf := make([]byte, 0, len(data)+1)
		buf = append(buf, byte(i))
		buf = append(buf, data...)
		sum := sha256.Sum256(buf)
		var v uint64
		for _, b := range sum[:8] {
			v = (v << 8) | uint64(b)
		}
		out[i] = int64(v % uint64(f.numBits))
	}
	return out
}

func (f *Filter) setBit(pos int64) {
	byteIdx := pos / 8
	bitIdx := uint(pos % 8)
	f.bits[byteIdx] |= 1 << bitIdx
}

func (f *Filter) getBit(pos int64) bool {
	byteIdx := pos / 8
	bitIdx := uint(pos % 8)
	return f.bits[byteIdx]&(1<<bitIdx) != 0
}

// Add inserts an item into the filter.
func (f *Filter) Add(data []byte) {
	for _, pos := range f.hashes(data) {
		f.setBit(pos)
	}
}

// MightContain reports whether the item may have been added. False
// positives are possible; false negatives are not.
func (f *Filter) MightContain(data []byte) bool {
	for _, pos := range f.hashes(data) {
		if !f.getBit(pos) {
			return false
		}
	}
	return true
}

// NumBits returns the size of the underlying bit array.
func (f *Filter) NumBits() int64 {
	return f.numBits
}

// K returns the number of hash functions used.
func (f *Filter) K() int {
	return f.k
}

package escrow

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Status represents the lifecycle of an escrow deal.
type Status int

const (
	StatusFunded Status = iota
	StatusReleased
	StatusRefunded
	StatusDisputed
	StatusResolved
)

func (s Status) String() string {
	switch s {
	case StatusFunded:
		return "funded"
	case StatusReleased:
		return "released"
	case StatusRefunded:
		return "refunded"
	case StatusDisputed:
		return "disputed"
	case StatusResolved:
		return "resolved"
	default:
		return "unknown"
	}
}

// Deal is a generic two-party escrow with an optional arbiter for disputes.
type Deal struct {
	ID       int64
	Buyer    address
	Seller   address
	Arbiter  address // address("") if none configured
	Amount   int64
	Status   Status
	CreatedAt int64
}

var (
	deals  *avl.Tree // id (string) -> *Deal
	nextID int64
)

func init() {
	deals = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("escrow: must be a direct user call")
	}
	return cur.Previous().Address()
}

func idKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func getDeal(id int64) *Deal {
	key := idKey(id)
	if !deals.Has(key) {
		panic("escrow: deal not found")
	}
	raw := deals.Get(key)
	return raw.(*Deal)
}

// CreateDeal opens a new escrow, funded by the buyer, for a given seller.
// An optional arbiter can be set to resolve disputes; pass address("") for none.
func CreateDeal(cur realm, seller address, arbiter address) int64 {
	caller := assertUserCall(cur)
	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount <= 0 {
		panic("escrow: must fund the deal with ugnot")
	}
	if seller == caller {
		panic("escrow: buyer and seller must differ")
	}

	id := nextID
	nextID++

	deals.Set(idKey(id), &Deal{
		ID:        id,
		Buyer:     caller,
		Seller:    seller,
		Arbiter:   arbiter,
		Amount:    amount,
		Status:    StatusFunded,
		CreatedAt: runtime.ChainHeight(),
	})
	return id
}

// Release lets the buyer release funds to the seller once satisfied.
func Release(cur realm, id int64) {
	caller := assertUserCall(cur)
	d := getDeal(id)
	if d.Status != StatusFunded {
		panic("escrow: deal is not in fundable state")
	}
	if caller != d.Buyer {
		panic("escrow: only the buyer can release funds")
	}

	payout(cur, d, d.Seller)
	d.Status = StatusReleased
}

// RequestRefund lets the seller voluntarily refund the buyer (e.g. cannot fulfill).
func RequestRefund(cur realm, id int64) {
	caller := assertUserCall(cur)
	d := getDeal(id)
	if d.Status != StatusFunded {
		panic("escrow: deal is not in fundable state")
	}
	if caller != d.Seller {
		panic("escrow: only the seller can initiate a refund")
	}

	payout(cur, d, d.Buyer)
	d.Status = StatusRefunded
}

// Dispute lets either party flag the deal for arbiter review.
func Dispute(cur realm, id int64) {
	caller := assertUserCall(cur)
	d := getDeal(id)
	if d.Status != StatusFunded {
		panic("escrow: deal is not in fundable state")
	}
	if caller != d.Buyer && caller != d.Seller {
		panic("escrow: only buyer or seller can dispute")
	}
	if d.Arbiter == address("") {
		panic("escrow: no arbiter configured for this deal")
	}
	d.Status = StatusDisputed
}

// ResolveDispute lets the configured arbiter decide the outcome.
func ResolveDispute(cur realm, id int64, payToSeller bool) {
	caller := assertUserCall(cur)
	d := getDeal(id)
	if d.Status != StatusDisputed {
		panic("escrow: deal is not under dispute")
	}
	if caller != d.Arbiter {
		panic("escrow: only the arbiter can resolve")
	}

	if payToSeller {
		payout(cur, d, d.Seller)
	} else {
		payout(cur, d, d.Buyer)
	}
	d.Status = StatusResolved
}

func payout(cur realm, d *Deal, to address) {
	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := d.Amount
	if amount > have {
		amount = have
	}
	if amount > 0 {
		bk.SendCoins(realmAddr, to, chain.Coins{chain.NewCoin("ugnot", amount)})
	}
}

func Render(path string) string {
	out := "# Escrow\n\n"
	out += ufmt.Sprintf("Total deals: %d\n\n", deals.Size())
	deals.Iterate("", "", func(key string, value interface{}) bool {
		d := value.(*Deal)
		out += ufmt.Sprintf("## #%d\n", d.ID)
		out += ufmt.Sprintf("Buyer: %s | Seller: %s | Amount: %d ugnot | Status: %s\n\n",
			d.Buyer, d.Seller, d.Amount, d.Status.String())
		return false
	})
	return out
}

package votingbooth

import (
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Poll is a simple single-choice, multi-option poll. One vote per address.
type Poll struct {
	ID        int64
	Creator   address
	Question  string
	Options   []string
	VoteCount []int64
	Voters    *avl.Tree // addr -> int64 (option index chosen)
	ClosesAt  int64
	Closed    bool
}

var (
	polls  *avl.Tree // id (string) -> *Poll
	nextID int64
)

func init() {
	polls = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("votingbooth: must be a direct user call")
	}
	return cur.Previous().Address()
}

func idKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func getPoll(id int64) *Poll {
	key := idKey(id)
	if !polls.Has(key) {
		panic("votingbooth: poll not found")
	}
	raw := polls.Get(key)
	return raw.(*Poll)
}

// CreatePoll opens a new poll with the given options, open for durationBlocks.
func CreatePoll(cur realm, question string, opt0 string, opt1 string, opt2 string, opt3 string, durationBlocks int64) int64 {
	caller := assertUserCall(cur)
	if question == "" {
		panic("votingbooth: question required")
	}
	if durationBlocks <= 0 {
		panic("votingbooth: durationBlocks must be positive")
	}

	options := []string{}
	for _, o := range []string{opt0, opt1, opt2, opt3} {
		if o != "" {
			options = append(options, o)
		}
	}
	if len(options) < 2 {
		panic("votingbooth: at least 2 non-empty options required")
	}

	id := nextID
	nextID++

	polls.Set(idKey(id), &Poll{
		ID:        id,
		Creator:   caller,
		Question:  question,
		Options:   options,
		VoteCount: make([]int64, len(options)),
		Voters:    avl.NewTree(),
		ClosesAt:  runtime.ChainHeight() + durationBlocks,
		Closed:    false,
	})
	return id
}

// Vote casts a single vote for optionIdx. One vote per address, no changing.
func Vote(cur realm, id int64, optionIdx int64) {
	caller := assertUserCall(cur)
	p := getPoll(id)
	if p.Closed {
		panic("votingbooth: poll is closed")
	}
	if runtime.ChainHeight() > p.ClosesAt {
		panic("votingbooth: voting period has ended, call ClosePoll")
	}
	if optionIdx < 0 || int(optionIdx) >= len(p.Options) {
		panic("votingbooth: invalid option index")
	}
	if p.Voters.Has(string(caller)) {
		panic("votingbooth: already voted")
	}

	p.Voters.Set(string(caller), optionIdx)
	p.VoteCount[optionIdx]++
}

// ClosePoll marks a poll as closed once its duration has elapsed.
func ClosePoll(cur realm, id int64) {
	assertUserCall(cur)
	p := getPoll(id)
	if p.Closed {
		panic("votingbooth: poll already closed")
	}
	if runtime.ChainHeight() <= p.ClosesAt {
		panic("votingbooth: voting period has not ended yet")
	}
	p.Closed = true
}

// Winner returns the index of the option with the most votes.
// Panics if the poll is still open or if there's a tie.
func Winner(id int64) int64 {
	p := getPoll(id)
	if !p.Closed {
		panic("votingbooth: poll is still open")
	}
	best := int64(0)
	bestIdx := int64(-1)
	tie := false
	for i, c := range p.VoteCount {
		if c > best {
			best = c
			bestIdx = int64(i)
			tie = false
		} else if c == best && best > 0 {
			tie = true
		}
	}
	if tie {
		panic("votingbooth: poll ended in a tie")
	}
	if bestIdx < 0 {
		panic("votingbooth: no votes cast")
	}
	return bestIdx
}

func Render(path string) string {
	out := "# Voting Booth\n\n"
	out += ufmt.Sprintf("Total polls: %d\n\n", polls.Size())
	polls.Iterate("", "", func(key string, value interface{}) bool {
		p := value.(*Poll)
		out += ufmt.Sprintf("## #%d: %s\n", p.ID, p.Question)
		status := "open"
		if p.Closed {
			status = "closed"
		}
		out += ufmt.Sprintf("Status: %s\n", status)
		for i, opt := range p.Options {
			out += ufmt.Sprintf("- %s: %d votes\n", opt, p.VoteCount[i])
		}
		out += "\n"
		return false
	})
	return out
}

package leaderboard

import (
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt/ringbuffer"
)

// PlayerRecord holds a player's cumulative score and recent score history.
type PlayerRecord struct {
	Player     address
	TotalScore int64
	Submissions int64
	History    *ringbuffer.Buffer // last N individual score submissions
	LastSubmitAt int64
}

const historyCapacity = 10

var (
	admin   address
	records *avl.Tree // addr -> *PlayerRecord
)

func init() {
	admin = address("g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt")
	records = avl.NewTree()
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("leaderboard: must be a direct user call")
	}
	return cur.Previous().Address()
}

// SubmitScore lets a player submit a new score, adding to their cumulative total.
func SubmitScore(cur realm, score int64) {
	caller := assertUserCall(cur)
	if score < 0 {
		panic("leaderboard: score must be non-negative")
	}

	key := string(caller)
	var rec *PlayerRecord
	if records.Has(key) {
		rec = records.Get(key).(*PlayerRecord)
	} else {
		rec = &PlayerRecord{
			Player:  caller,
			History: ringbuffer.New(historyCapacity),
		}
		records.Set(key, rec)
	}

	rec.TotalScore += score
	rec.Submissions++
	rec.History.Push(score)
	rec.LastSubmitAt = runtime.ChainHeight()
}

// GetScore returns a player's cumulative total score.
func GetScore(player address) int64 {
	key := string(player)
	if !records.Has(key) {
		return 0
	}
	rec := records.Get(key).(*PlayerRecord)
	return rec.TotalScore
}

// GetAverage returns a player's average score over their recent history window.
func GetAverage(player address) int64 {
	key := string(player)
	if !records.Has(key) {
		panic("leaderboard: no record for player")
	}
	rec := records.Get(key).(*PlayerRecord)
	return rec.History.Average()
}

// ResetPlayer lets the admin clear a single player's record (e.g. moderation).
func ResetPlayer(cur realm, player address) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("leaderboard: admin only")
	}
	key := string(player)
	if records.Has(key) {
		records.Remove(key)
	}
}

// Top returns up to n (player, score) pairs sorted by total score descending.
// This does a full scan; fine for moderate leaderboard sizes.
func topN(n int) ([]address, []int64) {
	type pair struct {
		addr  address
		score int64
	}
	all := []pair{}
	records.Iterate("", "", func(key string, value interface{}) bool {
		rec := value.(*PlayerRecord)
		all = append(all, pair{addr: rec.Player, score: rec.TotalScore})
		return false
	})

	// simple insertion sort descending by score
	for i := 1; i < len(all); i++ {
		k := all[i]
		j := i - 1
		for j >= 0 && all[j].score < k.score {
			all[j+1] = all[j]
			j--
		}
		all[j+1] = k
	}

	if n > len(all) {
		n = len(all)
	}
	addrs := make([]address, n)
	scores := make([]int64, n)
	for i := 0; i < n; i++ {
		addrs[i] = all[i].addr
		scores[i] = all[i].score
	}
	return addrs, scores
}

func Render(path string) string {
	out := "# Leaderboard\n\n"
	out += ufmt.Sprintf("Total players: %d\n\n", records.Size())
	addrs, scores := topN(10)
	for i := range addrs {
		out += ufmt.Sprintf("%d. %s - %d points\n", i+1, addrs[i], scores[i])
	}
	return out
}

// Forwards whatever ugnot is attached to Forward() on to `to`.
// Deployment plumbing only: it lets funds reach a locally-managed key so
// the real realms can be deployed from disk rather than retyped inline.
package payout

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

func Forward(cur realm, to address) {
	if !to.IsValid() {
		panic("payout: invalid destination")
	}
	amt := unsafe.OriginSend().AmountOf("ugnot")
	if amt <= 0 {
		panic("payout: nothing attached")
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin("ugnot", amt)})
}

package grc721

import (
	"chain"
	"math/overflow"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

type BasicNFT struct {
	name              string
	symbol            string
	origRealm         string   // owning realm's package path
	owners            avl.Tree // tokenId -> OwnerAddress
	balances          avl.Tree // OwnerAddress -> TokenCount
	tokenApprovals    avl.Tree // TokenId -> ApprovedAddress
	tokenURIs         avl.Tree // TokenId -> URIs
	operatorApprovals avl.Tree // "OwnerAddress:OperatorAddress" -> bool
}

func NewBasicNFT(_ int, rlm realm, name, symbol string) *BasicNFT {
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}
	pkgPath := rlm.PkgPath()
	if pkgPath == "" {
		panic(ErrNotRealm)
	}
	if !validName(name) {
		panic(ErrInvalidName)
	}
	if !validSymbol(symbol) {
		panic(ErrInvalidSymbol)
	}

	return &BasicNFT{
		name:      name,
		symbol:    symbol,
		origRealm: pkgPath,

		owners:            avl.Tree{},
		balances:          avl.Tree{},
		tokenApprovals:    avl.Tree{},
		tokenURIs:         avl.Tree{},
		operatorApprovals: avl.Tree{},
	}
}

func (s *BasicNFT) Name() string      { return s.name }
func (s *BasicNFT) Symbol() string    { return s.symbol }
func (s *BasicNFT) TokenCount() int64 { return int64(s.owners.Size()) }

func (s *BasicNFT) ID() string {
	return s.origRealm + "." + s.symbol
}

// BalanceOf returns balance of input address
func (s *BasicNFT) BalanceOf(addr address) (int64, error) {
	if err := isValidAddress(addr); err != nil {
		return 0, err
	}

	balance := s.balances.Get(addr.String())
	if balance == nil {
		return 0, nil
	}

	return balance.(int64), nil
}

// OwnerOf returns owner of input token id
func (s *BasicNFT) OwnerOf(tid TokenID) (address, error) {
	owner := s.owners.Get(string(tid))
	if owner == nil {
		return "", ErrInvalidTokenId
	}

	return owner.(address), nil
}

// TokenURI returns the URI of input token id
func (s *BasicNFT) TokenURI(tid TokenID) (string, error) {
	uri := s.tokenURIs.Get(tid.String())
	if uri == nil {
		return "", ErrInvalidTokenId
	}

	return uri.(string), nil
}

// SetTokenURI sets the URI of a token. caller must equal the token's
// owner. The owning realm's public wrapper is responsible for deriving
// caller from rlm.Previous().Address() under an rlm.IsCurrent() guard
// before invoking this method; this method trusts the supplied caller.
func (s *BasicNFT) SetTokenURI(caller address, tid TokenID, tURI TokenURI) (bool, error) {
	// check for invalid TokenID
	if !s.exists(tid) {
		return false, ErrInvalidTokenId
	}

	// check for the right owner
	owner, err := s.OwnerOf(tid)
	if err != nil {
		return false, err
	}
	if caller != owner {
		return false, ErrCallerIsNotOwner
	}
	s.tokenURIs.Set(tid.String(), tURI.String())

	chain.Emit(
		TokenURIUpdateEvent,
		"token", s.ID(),
		"tokenId", tid.String(),
	)

	return true, nil
}

// IsApprovedForAll returns true if operator is approved for all by the owner.
// Otherwise, returns false
func (s *BasicNFT) IsApprovedForAll(owner, operator address) bool {
	key := owner.String() + ":" + operator.String()
	approved := s.operatorApprovals.Get(key)
	if approved == nil {
		return false
	}

	return approved.(bool)
}

// Approve approves the input address for a particular token. caller
// must be the owner OR an operator approved for all on owner's behalf.
// The owning realm's wrapper validates IsCurrent and derives caller
// from rlm.Previous().Address() before calling.
func (s *BasicNFT) Approve(caller, to address, tid TokenID) error {
	if err := isValidAddress(to); err != nil {
		return err
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner == to {
		return ErrApprovalToCurrentOwner
	}

	if caller != owner && !s.IsApprovedForAll(owner, caller) {
		return ErrCallerIsNotOwnerOrApproved
	}

	tidStr := tid.String()
	s.tokenApprovals.Set(tidStr, to)

	chain.Emit(
		ApprovalEvent,
		"token", s.ID(),
		"owner", owner.String(),
		"to", to.String(),
		"tokenId", tidStr,
	)

	return nil
}

// GetApproved return the approved address for token
func (s *BasicNFT) GetApproved(tid TokenID) (address, error) {
	addr := s.tokenApprovals.Get(tid.String())
	if addr == nil {
		return zeroAddress, ErrTokenIdNotHasApproved
	}

	return addr.(address), nil
}

// SetApprovalForAll grants/revokes operator permission across all of
// the caller's tokens. caller is the owner whose approvals are mutated;
// the owning realm's wrapper derives it from rlm.Previous().Address()
// under an IsCurrent() guard.
func (s *BasicNFT) SetApprovalForAll(caller, operator address, approved bool) error {
	if err := isValidAddress(operator); err != nil {
		return ErrInvalidAddress
	}
	return s.setApprovalForAll(caller, operator, approved)
}

// SafeTransferFrom transfers a token from `from` to `to`, checking that
// contract recipients are aware of the GRC721 protocol to prevent
// tokens from being forever locked. caller must be the owner or an
// approved operator. The owning realm's wrapper derives caller from
// rlm.Previous().Address() under an IsCurrent() guard.
func (s *BasicNFT) SafeTransferFrom(caller, from, to address, tid TokenID) error {
	if !s.isApprovedOrOwner(caller, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	err := s.transfer(from, to, tid)
	if err != nil {
		return err
	}

	if !s.checkOnGRC721Received(from, to, tid) {
		return ErrTransferToNonGRC721Receiver
	}

	return nil
}

// TransferFrom transfers a token from `from` to `to`. Same caller
// contract as SafeTransferFrom.
func (s *BasicNFT) TransferFrom(caller, from, to address, tid TokenID) error {
	if !s.isApprovedOrOwner(caller, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	err := s.transfer(from, to, tid)
	if err != nil {
		return err
	}

	return nil
}

// Mints `tokenId` and transfers it to `to`.
func (s *BasicNFT) Mint(to address, tid TokenID) error {
	return s.mint(to, tid)
}

// Mints `tokenId` and transfers it to `to`. Also checks that
// contract recipients are using GRC721 protocol
func (s *BasicNFT) SafeMint(to address, tid TokenID) error {
	err := s.mint(to, tid)
	if err != nil {
		return err
	}

	if !s.checkOnGRC721Received(zeroAddress, to, tid) {
		return ErrTransferToNonGRC721Receiver
	}

	return nil
}

func (s *BasicNFT) Burn(tid TokenID) error {
	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}

	s.beforeTokenTransfer(owner, zeroAddress, tid, 1)

	tidStr := tid.String()
	s.tokenApprovals.Remove(tidStr)
	balance, err := s.BalanceOf(owner)
	if err != nil {
		return err
	}
	balance = overflow.Sub64p(balance, 1)

	ownerStr := owner.String()
	s.balances.Set(ownerStr, balance)
	s.owners.Remove(tidStr)

	chain.Emit(
		BurnEvent,
		"token", s.ID(),
		"from", ownerStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(owner, zeroAddress, tid, 1)

	return nil
}

/* Helper methods */

// Helper for SetApprovalForAll()
func (s *BasicNFT) setApprovalForAll(owner, operator address, approved bool) error {
	if owner == operator {
		return ErrApprovalToCurrentOwner
	}

	key := owner.String() + ":" + operator.String()
	s.operatorApprovals.Set(key, approved)

	chain.Emit(
		ApprovalForAllEvent,
		"token", s.ID(),
		"owner", owner.String(),
		"to", operator.String(),
		"approved", strconv.FormatBool(approved),
	)

	return nil
}

// Helper for TransferFrom() and SafeTransferFrom()
func (s *BasicNFT) transfer(from, to address, tid TokenID) error {
	if err := isValidAddress(from); err != nil {
		return ErrInvalidAddress
	}
	if err := isValidAddress(to); err != nil {
		return ErrInvalidAddress
	}

	if from == to {
		return ErrCannotTransferToSelf
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	s.beforeTokenTransfer(from, to, tid, 1)

	// Check that tokenId was not transferred by `beforeTokenTransfer`
	owner, err = s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	tidStr := tid.String()
	s.tokenApprovals.Remove(tidStr)
	fromBalance, err := s.BalanceOf(from)
	if err != nil {
		return err
	}
	toBalance, err := s.BalanceOf(to)
	if err != nil {
		return err
	}
	fromBalance = overflow.Sub64p(fromBalance, 1)
	toBalance = overflow.Add64p(toBalance, 1)

	fromStr := from.String()
	toStr := to.String()

	s.balances.Set(fromStr, fromBalance)
	s.balances.Set(toStr, toBalance)
	s.owners.Set(tidStr, to)

	chain.Emit(
		TransferEvent,
		"token", s.ID(),
		"from", fromStr,
		"to", toStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(from, to, tid, 1)

	return nil
}

// Helper for Mint() and SafeMint()
func (s *BasicNFT) mint(to address, tid TokenID) error {
	if err := isValidAddress(to); err != nil {
		return err
	}

	if s.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	s.beforeTokenTransfer(zeroAddress, to, tid, 1)

	// Check that tokenId was not minted by `beforeTokenTransfer`
	if s.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	toBalance, err := s.BalanceOf(to)
	if err != nil {
		return err
	}
	toBalance = overflow.Add64p(toBalance, 1)
	toStr := to.String()
	tidStr := tid.String()
	s.balances.Set(toStr, toBalance)
	s.owners.Set(tidStr, to)

	chain.Emit(
		MintEvent,
		"token", s.ID(),
		"to", toStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(zeroAddress, to, tid, 1)

	return nil
}

func (s *BasicNFT) isApprovedOrOwner(addr address, tid TokenID) bool {
	owner := s.owners.Get(tid.String())
	if owner == nil {
		return false
	}

	ownerAddr := owner.(address)
	if addr == ownerAddr || s.IsApprovedForAll(ownerAddr, addr) {
		return true
	}

	approved, err := s.GetApproved(tid)
	if err != nil {
		return false
	}

	return approved == addr
}

// Checks if token id already exists
func (s *BasicNFT) exists(tid TokenID) bool {
	return s.owners.Has(tid.String())
}

func (s *BasicNFT) beforeTokenTransfer(from, to address, firstTokenId TokenID, batchSize int64) {
	// TODO: Implementation
}

func (s *BasicNFT) afterTokenTransfer(from, to address, firstTokenId TokenID, batchSize int64) {
	// TODO: Implementation
}

func (s *BasicNFT) checkOnGRC721Received(from, to address, tid TokenID) bool {
	// TODO: Implementation
	return true
}

func (s *BasicNFT) RenderHome() (str string) {
	str += ufmt.Sprintf("# %s ($%s)\n\n", s.name, s.symbol)
	str += ufmt.Sprintf("* **Total supply**: %d\n", s.TokenCount())
	str += ufmt.Sprintf("* **Known accounts**: %d\n", s.balances.Size())

	return
}

// Getter returns an NFTGetter that yields a reader-only view of the NFT.
// Safe to register with cross-realm aggregators like tokenhub — readers
// only, no rlm-typed methods, so no cur can be captured via this surface.
func (n *BasicNFT) Getter() NFTGetter {
	return func() IGRC721Reader {
		return n
	}
}

