package nsdata

// The real human-facing view moved OUT of this realm into `nsview`
// (2026-08-21), after an adversarial review found three separate
// defects in the old Render() — unescaped profile-field injection into
// the markdown, an O(domains × names) home page any user could inflate
// into a permanent DoS, and links that 404'd — none of which could ever
// be fixed, because this realm is deployed once and never replaced.
//
// The lesson generalised: "it's only display code, it has no
// authorization surface" was the wrong test for what belongs in an
// immutable realm. The right test is whether a bug in it would be
// permanent. Display code changes far more often than storage schemas
// do, so it belongs in something swappable.
//
// What remains here is deliberately a fixed string: no user-authored
// data, no iteration over state, nothing that can be wrong later.
func Render(path string) string {
	return "# Meme Name Service — data realm\n\n" +
		"This realm stores records only: name and domain ownership, " +
		"configuration, and the NFT state.\n\n" +
		"The human-facing view lives in the `nsview` realm; writes go " +
		"through `nslogic`.\n"
}

// Package nsdata is the permanent vault — the one realm in the system
// that can never be replaced, because it holds every record. nslogic
// and nsview are swappable: deploy a new one, re-point, done. A "new
// nsdata" is an empty registry, so whatever ships here ships forever.
//
// Everything in this file is written under that constraint, which
// produces two rules the rest of the realm follows:
//
//  1. NOTHING IS A CONSTANT. Term length, grace period, size caps —
//     all of it is a variable with a setter. A `const` here is a
//     decision that can never be revisited, and there is no value in
//     this system worth that. (Grace period was the one that prompted
//     this; the reasoning applies to all of them equally.)
//
//  2. THE VAULT STORES, IT DOES NOT DECIDE. Business policy — pricing
//     math, validation, what a profile field means, how a page looks —
//     lives in the swappable realms. This realm keeps records, gates
//     writes, and stays out of the way. Anything it "knows" is a rule
//     that can never be changed.
//
// Rule 2 is why Domain and Name carry an `extra` tree instead of a
// growing list of typed fields. A struct field cannot be added after
// deployment, so every feature nobody thought of yet would be
// permanently unbuildable. Profile fields, per-domain pricing, tier
// markers, cross-chain addresses, key hashes — all of it lives in
// `extra`, written by whichever logic realm is current. New feature,
// new key: a logic swap, not a migration that cannot happen.
package nsdata

import (
	"time"

	"gno.land/p/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/grc721"
	"gno.land/p/nt/avl/v0"
)

type Domain struct {
	label      string
	owner      address
	registered time.Time
	expires    time.Time
	streak     int64
	frozen     bool

	// Pricing, and anything a future logic realm needs. Not typed
	// fields, because pricing is policy and policy belongs in the
	// swappable half — the vault only has to remember the values.
	extra avl.Tree
}

type Name struct {
	label      string
	domain     string
	owner      address
	registered time.Time
	expires    time.Time
	streak     int64
	frozen     bool

	// Whether a GRC-721 token was actually minted for this record.
	// Typed rather than an `extra` key because it gates real branching
	// (burn on reclaim, transferability) on hot paths, and getting it
	// wrong desynchronises the two ownership ledgers. The free tier
	// (SPEC.md §19) registers names with this false.
	isNFT bool

	// Profile fields, cross-chain addresses, management-key hashes,
	// tier markers — see the package comment.
	extra avl.Tree
}

var (
	nft *grc721.BasicNFT

	domains avl.Tree
	names   avl.Tree
	primary avl.Tree

	// Package-level extension slot, same reasoning as Domain/Name.extra:
	// somewhere to put global state nobody has thought of yet (points
	// balances, claim records, a custodian address) without needing a
	// new package var that cannot be added later.
	globals avl.Tree

	admin address // the vault door — see governance.gno for the full role model

	// The set of realms currently allowed to call mutations. A set, not a
	// single address, because the project will plausibly grow more than
	// one writer (a free-tier realm, a custodial relayer) and a single
	// slot would force them all into one realm.
	trustedLogicSet avl.Tree

	// -- config: every value below is settable, none is a const --
	treasury    address
	termLength  = 365 * 24 * time.Hour
	gracePeriod = 90 * 24 * time.Hour

	labelPattern = `^[a-z0-9]+(-[a-z0-9]+)*$`
	minLabelLen  = 1
	maxLabelLen  = 63

	// Bounds on the extension slots. Storage written here is permanent
	// and paid for by the realm, so unbounded strings are griefing.
	maxExtraKeyLen   = 32
	maxExtraValueLen = 512
	maxExtraEntries  = 24

	// Prefix for TokenURI. Points at whichever view realm currently
	// renders the artwork; settable so the art can be replaced without
	// touching this realm. See nft.gno.
	tokenURIBase = "/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsview:token/"
)

func init(cur realm) {
	nft = grc721.NewBasicNFT(0, cur, "Meme Name Service", "MNS")
	deployer := cur.Previous().Address()
	admin = deployer
	recovery = deployer
	treasury = deployer
	// The trusted-logic set starts EMPTY and timelockDelay starts at
	// zero: deploy nsdata, deploy nslogic, then propose+execute the
	// grant. No mutation is callable until that happens.
	//
	// FIRST OPERATIONAL STEP AFTER DEPLOY, before anything of value
	// exists here: move `recovery` to a key held separately from
	// `admin` (ideally cold, ideally a multisig), then raise
	// timelockDelay. Until that is done both roles are the same key and
	// the whole recovery design is inert — it protects against one key
	// being lost or stolen, not against one key being both.
}

package nsdata

import (
	"errors"
	"strings"
	"time"

	"gno.land/p/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/grc721"
	"gno.land/p/nt/avl/v0"
)

// Every function here is gated to trustedLogic and does exactly what it
// is told. Authorization beyond "is this the current logic realm" is
// deliberately NOT duplicated here: the vault stores, the logic realm
// decides. Re-checking policy in an unfixable realm sounds safer but
// bakes today's rules in permanently — a future feature that legitimately
// needs an admin to touch someone's record would be unbuildable.

// -- domains --

func RegisterDomainRecord(cur realm, label string, owner address, now time.Time) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	if d, ok := getDomain(label); ok {
		if d.frozen {
			return errStr("domain is frozen")
		}
		if !isReclaimable(d.expires, now) {
			return errStr("domain already registered and not yet reclaimable")
		}
		clearPrimaryIfPointingAt(d.owner, domainTokenID(label))
		mustBurn(domainTokenID(label))
		domains.Remove(label)
	}
	domains.Set(label, &Domain{
		label: label, owner: owner, registered: now, expires: now.Add(termLength),
		extra: avl.Tree{},
	})
	mustMint(owner, domainTokenID(label))
	return nil
}

func RenewDomainRecord(cur realm, label string, caller address, now time.Time) error {
	assertIsTrustedLogic(cur)
	d, ok := getDomain(label)
	if !ok {
		return errStr("unknown domain")
	}
	if isReclaimable(d.expires, now) {
		return errStr("domain expired beyond grace period")
	}
	if caller != d.owner {
		return errStr("restricted to domain owner")
	}
	d.expires, d.streak = advanceTerm(d.expires, d.streak, now)
	return nil
}

// advanceTerm extends a term by exactly one term-length from its
// PREVIOUS due date (never from `now` — the grace period must not
// extend the term) and returns the new streak.
//
// The streak guard is the part worth reading twice. Streak used to be
// incremented once per CALL, with no rate limit — so a "10 year diamond
// hands streak", rendered as a longevity signal, was buyable in a single
// block by calling renew ten times. It now only increments when the
// caller has actually lived into the final term of what they are
// renewing, making it a measure of elapsed time rather than of
// transactions sent.
//
// Deliberate tradeoff: renewing far in advance still extends the term
// but does not grow the streak, because no time has been survived yet.
// Renewing during grace resets the streak to 1 — the name was not lost,
// but the run of on-time renewals was broken.
func advanceTerm(expires time.Time, streak int64, now time.Time) (time.Time, int64) {
	onTime := isValidNow(expires, now)
	livedTheTerm := !now.Before(expires.Add(-termLength))
	next := expires.Add(termLength)
	// Anchoring to the previous due date is only safe while a renewal
	// cannot happen more than one term after it — i.e. while
	// gracePeriod <= termLength. That invariant held silently under the
	// old hardcoded constants and stopped holding the moment both became
	// settable: with a grace period longer than the term, a renewal paid
	// late in grace would return an expiry ALREADY IN THE PAST, leaving
	// the payer with a name that is still expired. Clamp forward so a
	// paid renewal always buys a live term, while keeping the anchor
	// behaviour in every normal case.
	if !next.After(now) {
		next = now.Add(termLength)
	}
	switch {
	case !onTime:
		return next, 1
	case livedTheTerm:
		return next, streak + 1
	default:
		return next, streak
	}
}

func SetDomainFrozen(cur realm, label string, frozen bool) {
	assertIsTrustedLogic(cur)
	mustGetDomain(label).frozen = frozen
}

func SetDomainExpiryRecord(cur realm, label string, expires time.Time) {
	assertIsTrustedLogic(cur)
	mustGetDomain(label).expires = expires
}

// SetDomainExtraRecord writes one arbitrary key on a domain — pricing,
// or whatever a future logic realm needs. An empty value deletes the
// key, so storage can be reclaimed.
func SetDomainExtraRecord(cur realm, label, key, value string) error {
	assertIsTrustedLogic(cur)
	d, ok := getDomain(label)
	if !ok {
		return errStr("unknown domain")
	}
	return setExtra(&d.extra, key, value)
}

// -- names --

// RegisterNameRecord mints `label*domain`. mintNFT=false registers the
// record WITHOUT a GRC-721 token — the free tier (SPEC.md §19), where
// the per-mint token storage cost is not worth paying for a giveaway.
// Such a record is upgradeable later via PromoteToNFTRecord.
func RegisterNameRecord(cur realm, label, domainLabel string, owner address, now time.Time, mintNFT bool) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	d, ok := getDomain(domainLabel)
	if !ok {
		return errStr("unknown domain")
	}
	if d.frozen {
		return errStr("domain is frozen")
	}
	if isReclaimable(d.expires, now) {
		return errStr("domain has lapsed past its grace period")
	}
	treeKey := nameTreeKey(label, domainLabel)
	tid := nameTokenID(label, domainLabel)
	if n, ok := getName(label, domainLabel); ok {
		if n.frozen {
			return errStr("name is frozen")
		}
		if !isReclaimable(n.expires, now) {
			return errStr("name already registered and not yet reclaimable")
		}
		// Evict the previous holder completely. Clearing the reverse
		// pointer FIRST matters: leaving it would make the old owner
		// resolve to a name the reclaimer now owns.
		clearPrimaryIfPointingAt(n.owner, tid)
		if n.isNFT {
			mustBurn(tid)
		}
		names.Remove(treeKey)
	}
	names.Set(treeKey, &Name{
		label: label, domain: domainLabel, owner: owner,
		registered: now, expires: now.Add(termLength),
		isNFT: mintNFT, extra: avl.Tree{},
	})
	if mintNFT {
		mustMint(owner, tid)
	}
	if primary.Get(owner.String()) == nil {
		primary.Set(owner.String(), tid)
	}
	return nil
}

// PromoteToNFTRecord mints the GRC-721 token for a record registered
// without one — the paid free-tier upgrade. Preserves expiry and streak;
// this is not a re-registration.
func PromoteToNFTRecord(cur realm, label, domainLabel string, newOwner address) error {
	assertIsTrustedLogic(cur)
	if !newOwner.IsValid() {
		return errStr("invalid owner address")
	}
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if n.isNFT {
		return errStr("name already has a token")
	}
	// Covers both upgrade paths: a holder who already had a wallet
	// (newOwner == n.owner) and a custodially-held name moving to the
	// claimant's now-real wallet in the same step.
	if newOwner != n.owner {
		clearPrimaryIfPointingAt(n.owner, nameTokenID(label, domainLabel))
		n.owner = newOwner
	}
	tid := nameTokenID(label, domainLabel)
	mustMint(n.owner, tid)
	n.isNFT = true
	// Same "first name becomes primary" rule as every other path that
	// changes ownership; without it a promoted name could leave its new
	// owner with no reverse resolution at all.
	if primary.Get(n.owner.String()) == nil {
		primary.Set(n.owner.String(), tid)
	}
	return nil
}

func RenewNameRecord(cur realm, label, domainLabel string, caller address, now time.Time) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if isReclaimable(n.expires, now) {
		return errStr("name expired beyond grace period")
	}
	if caller != n.owner {
		return errStr("restricted to name owner")
	}
	n.expires, n.streak = advanceTerm(n.expires, n.streak, now)
	return nil
}

func SetNameFrozen(cur realm, label, domainLabel string, frozen bool) {
	assertIsTrustedLogic(cur)
	mustGetName(label, domainLabel).frozen = frozen
}

// SetNameExpiryRecord sets an expiry directly. Backs the admin
// free-extension lever (SPEC.md §19) and any future term mechanic;
// the logic realm decides who may call it.
func SetNameExpiryRecord(cur realm, label, domainLabel string, expires time.Time) {
	assertIsTrustedLogic(cur)
	mustGetName(label, domainLabel).expires = expires
}

// SetNameExtraRecord writes one arbitrary key on a name. This is where
// profile fields, cross-chain addresses, management-key hashes and tier
// markers live. An empty value deletes the key.
func SetNameExtraRecord(cur realm, label, domainLabel, key, value string) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	return setExtra(&n.extra, key, value)
}

func SetPrimaryRecord(cur realm, owner address, label, domainLabel string) error {
	assertIsTrustedLogic(cur)
	if _, ok := getName(label, domainLabel); !ok {
		return errStr("unknown name")
	}
	primary.Set(owner.String(), nameTokenID(label, domainLabel))
	return nil
}

func ClearPrimaryRecord(cur realm, owner address) {
	assertIsTrustedLogic(cur)
	primary.Remove(owner.String())
}

// -- raw NFT operations (policy checks are the logic realm's job) --

func RawTransferNFT(cur realm, caller, from, to address, tid string) error {
	assertIsTrustedLogic(cur)
	if !to.IsValid() {
		return errStr("invalid recipient address")
	}
	if err := nft.TransferFrom(caller, from, to, grc721.TokenID(tid)); err != nil {
		return err
	}
	if strings.HasPrefix(tid, "*") {
		mustGetDomain(tid[1:]).owner = to
	} else {
		label, domainLabel := splitTokenID(tid)
		mustGetName(label, domainLabel).owner = to
	}
	// Ownership moved, so the sender's reverse pointer is now a lie — drop
	// it. The recipient is deliberately NOT given one: `to` is chosen by
	// the sender and never consents, so auto-assigning would let anyone
	// brand an arbitrary address's public reverse-resolution just by
	// gifting it a name. The recipient opts in via SetPrimaryRecord.
	// (It would also have written a DOMAIN token id into a tree that only
	// ever holds name ids.)
	clearPrimaryIfPointingAt(from, tid)
	return nil
}

// TransferRecordOwner moves a record that has no GRC-721 token (free
// tier), where RawTransferNFT cannot be used because the token layer has
// nothing to move.
func TransferRecordOwner(cur realm, label, domainLabel string, to address) error {
	assertIsTrustedLogic(cur)
	if !to.IsValid() {
		return errStr("invalid recipient address")
	}
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if n.isNFT {
		return errStr("name has a token; use RawTransferNFT")
	}
	tid := nameTokenID(label, domainLabel)
	clearPrimaryIfPointingAt(n.owner, tid)
	n.owner = to
	// No auto-assign for the recipient — see RawTransferNFT.
	return nil
}

func RawApprove(cur realm, caller, to address, tid string) error {
	assertIsTrustedLogic(cur)
	return nft.Approve(caller, to, grc721.TokenID(tid))
}

func RawSetApprovalForAll(cur realm, caller, operator address, approved bool) error {
	assertIsTrustedLogic(cur)
	return nft.SetApprovalForAll(caller, operator, approved)
}

// -- config: all settable, none constant --

func SetTreasuryRecord(cur realm, addr address)      { assertIsTrustedLogic(cur); treasury = addr }
func SetTermLengthRecord(cur realm, d time.Duration)  { assertIsTrustedLogic(cur); termLength = d }
func SetGracePeriodRecord(cur realm, d time.Duration) { assertIsTrustedLogic(cur); gracePeriod = d }
func SetLabelPatternRecord(cur realm, pattern string) { assertIsTrustedLogic(cur); labelPattern = pattern }
func SetTokenURIBaseRecord(cur realm, base string)    { assertIsTrustedLogic(cur); tokenURIBase = base }

func SetLabelLengthRecord(cur realm, minLen, maxLen int) {
	assertIsTrustedLogic(cur)
	minLabelLen, maxLabelLen = minLen, maxLen
}

func SetExtraLimitsRecord(cur realm, keyLen, valueLen, entries int) {
	assertIsTrustedLogic(cur)
	maxExtraKeyLen, maxExtraValueLen, maxExtraEntries = keyLen, valueLen, entries
}

// SetGlobalRecord writes one arbitrary package-level key — fee rates,
// default prices, a custodian address, points balances, claim records.
// Anything global that does not exist yet goes here instead of needing a
// package variable that could never be added after deployment.
func SetGlobalRecord(cur realm, key, value string) error {
	assertIsTrustedLogic(cur)
	return setExtra(&globals, key, value)
}

// setExtra applies the shared bounds and the delete-on-empty rule.
func setExtra(t *avl.Tree, key, value string) error {
	if err := assertExtraKey(key); err != nil {
		return err
	}
	if value == "" {
		t.Remove(key)
		return nil
	}
	if len(value) > maxExtraValueLen {
		return errStr("extra value too long")
	}
	if t.Get(key) == nil && t.Size() >= maxExtraEntries {
		return errStr("too many extra entries")
	}
	t.Set(key, value)
	return nil
}

// assertExtraKey keeps extension keys free of the characters that would
// make a snapshot ambiguous. Export lists keys as CSV, so a key
// containing a comma or a newline would silently corrupt a backup — and
// a backup you cannot trust is the one thing this realm cannot afford.
func assertExtraKey(key string) error {
	if key == "" || len(key) > maxExtraKeyLen {
		return errStr("bad extra key")
	}
	if strings.ContainsAny(key, ",\n\r") {
		return errStr("extra key may not contain commas or newlines")
	}
	return nil
}

// mustMint / mustBurn PANIC rather than returning an error, deliberately.
//
// In Gno a returned error does not revert anything — only a panic does.
// These calls happen AFTER the record has already been written, so a
// caller that merely logged the error would leave a record whose isNFT
// flag disagrees with the token ledger, permanently, in a realm that
// cannot be redeployed. A failure here is an internal invariant
// violation rather than a user-facing condition, so the correct response
// is to abort the whole transaction and leave no trace.
func mustMint(owner address, tid string) {
	if err := nft.Mint(owner, grc721.TokenID(tid)); err != nil {
		panic("nsdata: mint failed for " + tid + ": " + err.Error())
	}
}

func mustBurn(tid string) {
	if err := nft.Burn(grc721.TokenID(tid)); err != nil {
		panic("nsdata: burn failed for " + tid + ": " + err.Error())
	}
}

// assertLabelKeySafe is a STRUCTURAL check, not a policy one. Character
// policy lives in the logic realm's tunable labelPattern; this is the
// narrow set of characters that would break the vault's own machinery no
// matter what policy is in force:
//
//   "*"  is the separator in both key encodings, so a label containing
//        one makes storage keys and token ids ambiguous;
//   ","  and newlines would corrupt the CSV snapshot exports, which are
//        the disaster-recovery guarantee — assertExtraKey already refuses
//        them for extension keys, and labels become keys just as much;
//   ""   cannot address a record at all.
//
// Enforcing it here rather than trusting the logic realm matters because
// labelPattern is admin-tunable: loosening it must never be able to
// silently corrupt a backup in a realm that cannot be redeployed.
func assertLabelKeySafe(label string) error {
	if label == "" {
		return errStr("empty label")
	}
	if strings.ContainsAny(label, "*,\n\r") {
		return errStr("label may not contain '*', commas or newlines")
	}
	return nil
}

func errStr(s string) error { return errors.New(s) }

// Package nsview is the human-facing view — the third realm in the
// split, and the newest (2026-08-21).
//
// It exists because an adversarial review found three defects in the old
// Render(), which lived inside the permanent `nsdata` vault: unescaped
// profile text injected into the page markdown, an O(domains × names)
// home page any user could inflate into a permanent denial of service,
// and navigation links that 404'd. All three were display bugs, and none
// of them could ever have been fixed, because that realm is deployed
// exactly once. The NFT artwork moved here for the same reason.
//
// Display code is swappable now. This realm holds no state, reads
// everything from nsdata's exported API, and can be redeployed and
// re-pointed at any time with nothing to migrate.
package nsview

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// Profile keys inside a name's extension slot. Conventions owned by this
// realm and the logic realm, not by the vault — the vault stores strings
// and has no opinion about what they mean.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
)

func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "token/"):
		return "```\n" + BuildSVG(strings.TrimPrefix(path, "token/")) + "\n```\n"
	default:
		label, domainLabel := splitTokenID(path)
		if label == "" {
			return renderDomain(domainLabel)
		}
		return renderName(label, domainLabel)
	}
}

func renderHome() string {
	out := "# Meme Name Service\n\n"
	out += ufmt.Sprintf("%d domains registered.\n\n", nsdata.CountDomains())
	for _, label := range splitCSV(nsdata.ListDomains()) {
		owner, _, _, _, _ := nsdata.GetDomainInfo(label)
		// The link target must carry the "*" prefix — Render dispatches a
		// bare label to renderName, which 404s. That was the old home
		// page's bug: every link on it was dead.
		out += ufmt.Sprintf("- [*%s](*%s) — owner `%s` — %d name(s)\n",
			label, label, owner.String(), nsdata.CountNames(label))
	}
	return out
}

func renderDomain(domainLabel string) string {
	if !nsdata.DomainExists(domainLabel) {
		return "404: unknown domain\n"
	}
	owner, registered, expires, streak, frozen := nsdata.GetDomainInfo(domainLabel)
	status, _, daysLine := statusFields(expires)

	out := ufmt.Sprintf("# *%s\n\n", domainLabel)
	out += ufmt.Sprintf("- owner: `%s`\n", owner.String())
	out += ufmt.Sprintf("- status: **%s** (%s)\n", status, daysLine)
	if frozen {
		out += "- **frozen**\n"
	}
	out += ufmt.Sprintf("- registered: %s\n", registered.Format("2006-01-02"))
	out += ufmt.Sprintf("- renewal streak: %d year(s)\n\n", streak)

	count := nsdata.CountNames(domainLabel)
	out += ufmt.Sprintf("## %d name(s) under this domain\n\n", count)
	for _, label := range splitCSV(nsdata.ListNames(domainLabel)) {
		out += ufmt.Sprintf("- [%s*%s](%s*%s)\n", label, domainLabel, label, domainLabel)
	}
	if count == 0 {
		out += "_none yet_\n"
	}
	return out
}

func renderName(label, domainLabel string) string {
	if !nsdata.NameExists(label, domainLabel) {
		return "404: unknown name\n"
	}
	owner, registered, expires, streak, frozen, isNFT := nsdata.GetNameInfo(label, domainLabel)
	status, _, daysLine := statusFields(expires)

	out := ufmt.Sprintf("# %s*%s\n\n", label, domainLabel)
	out += ufmt.Sprintf("- owner: `%s`\n", owner.String())
	out += ufmt.Sprintf("- status: **%s** (%s)\n", status, daysLine)
	if frozen {
		out += "- **frozen**\n"
	}
	if !isNFT {
		out += "- free tier (no token minted yet)\n"
	}
	out += ufmt.Sprintf("- registered: %s\n", registered.Format("2006-01-02"))
	out += ufmt.Sprintf("- renewal streak: %d year(s)\n\n", streak)
	out += ufmt.Sprintf("- [*%s](*%s)\n\n", domainLabel, domainLabel)

	displayName := nsdata.GetNameExtra(label, domainLabel, keyDisplayName)
	bio := nsdata.GetNameExtra(label, domainLabel, keyBio)
	website := nsdata.GetNameExtra(label, domainLabel, keyWebsite)

	if displayName != "" || bio != "" || website != "" {
		out += "## Profile\n\n"
		// Every one of these is attacker-authored. Escaping them is the
		// whole reason this realm exists separately.
		if displayName != "" {
			out += ufmt.Sprintf("**%s**\n\n", escapeMarkdown(displayName))
		}
		if bio != "" {
			// A blockquote so even a crafted multi-line bio cannot break
			// out into block-level constructs.
			out += "> " + escapeMarkdown(bio) + "\n\n"
		}
		if website != "" {
			if isSafeURL(website) {
				out += ufmt.Sprintf("[%s](%s)\n\n", escapeMarkdown(website), website)
			} else {
				out += ufmt.Sprintf("website (unverified): `%s`\n\n", escapeMarkdown(website))
			}
		}
	}
	return out
}

// -- helpers --

func splitCSV(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

// splitTokenID splits `label*domain`; a leading "*" yields an empty
// label, which is how a domain page is addressed.
func splitTokenID(tid string) (label, domain string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

// escapeMarkdown neutralises user-authored text so it renders as the
// literal characters typed rather than as markup. Backslash-escapes the
// CommonMark ASCII punctuation set and folds newlines, which stops
// headings, lists, tables, images, links, and raw HTML alike.
func escapeMarkdown(s string) string {
	s = strings.ReplaceAll(s, "\r\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", " ")
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if strings.IndexByte("\\`*_{}[]()#+-.!|<>&~\"'", c) >= 0 {
			b.WriteByte('\\')
		}
		b.WriteByte(c)
	}
	return b.String()
}

// isSafeURL only admits plain http/https. Everything else — javascript:,
// data:, anything unrecognised — is refused a live link. Checked on read
// rather than on write so tightening the rule later also applies to
// profiles that already exist.
func isSafeURL(u string) bool {
	if !strings.HasPrefix(u, "http://") && !strings.HasPrefix(u, "https://") {
		return false
	}
	if len(u) > 256 {
		return false
	}
	// This value is emitted RAW as the markdown link destination, so it is
	// the one attacker-authored string on the page that escapeMarkdown
	// does not neutralise. Allow-list instead of deny-list: every byte
	// must be printable, non-space ASCII. A deny-list missed newlines,
	// which let a crafted `website` terminate the link and inject
	// arbitrary markdown into the page below it.
	for i := 0; i < len(u); i++ {
		c := u[i]
		if c <= 0x20 || c >= 0x7f {
			return false
		}
		if strings.IndexByte("()<>\"'\\`", c) >= 0 {
			return false
		}
	}
	return true
}

package nsview

import (
	"encoding/base64"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// The NFT artwork and every piece of display formatting live here, in a
// realm that can be redeployed, rather than in the vault that cannot.
// nsdata.TokenURI points at this realm through a settable prefix.

// TokenURI returns the full data: URI for a token, generated on every
// read so the image always reflects current state (never baked at mint).
func TokenURI(tid string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(BuildSVG(tid)))
}

func BuildSVG(tid string) string {
	var expires time.Time
	var streak int64
	var frozen bool

	if strings.HasPrefix(tid, "*") {
		label := tid[1:]
		if !nsdata.DomainExists(label) {
			return placeholderSVG("unknown")
		}
		_, _, expires, streak, frozen = nsdata.GetDomainInfo(label)
	} else {
		label, domainLabel := splitTokenID(tid)
		if !nsdata.NameExists(label, domainLabel) {
			return placeholderSVG("unknown")
		}
		_, _, expires, streak, frozen, _ = nsdata.GetNameInfo(label, domainLabel)
	}

	status, statusColor, daysLine := statusFields(expires)
	if frozen {
		status, statusColor = "FROZEN", "#8888aa"
	}

	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">
  <rect width="400" height="400" fill="#10101a"/>
  <rect x="12" y="12" width="376" height="376" rx="16" fill="none" stroke="%s" stroke-width="3"/>
  <text x="200" y="170" text-anchor="middle" font-family="monospace" font-size="30" font-weight="bold" fill="#ffffff">%s</text>

  <text x="200" y="215" text-anchor="middle" font-family="monospace" font-size="16" fill="#cccccc">
    <tspan>%s</tspan>
    <animate attributeName="opacity" values="1;1;0;0" keyTimes="0;0.499;0.5;1" dur="10s" repeatCount="indefinite"/>
  </text>
  <text x="200" y="215" text-anchor="middle" font-family="monospace" font-size="16" fill="#cccccc" opacity="0">
    <tspan>%s</tspan>
    <animate attributeName="opacity" values="0;0;1;1" keyTimes="0;0.499;0.5;1" dur="10s" repeatCount="indefinite"/>
  </text>

  <text x="200" y="245" text-anchor="middle" font-family="monospace" font-size="13" fill="#999999">%s</text>
  <text x="200" y="270" text-anchor="middle" font-family="monospace" font-size="13" fill="#999999">%d yr streak</text>
  <text x="200" y="360" text-anchor="middle" font-family="monospace" font-size="15" font-weight="bold" fill="%s">%s</text>
</svg>`,
		statusColor, escapeXML(tid),
		expires.Format("2006-01-02"), expires.Format("Jan 2, 2006"),
		daysLine, streak, statusColor, status)
}

func placeholderSVG(msg string) string {
	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">`+
		`<rect width="400" height="400" fill="#10101a"/>`+
		`<text x="200" y="200" text-anchor="middle" font-family="monospace" font-size="18" fill="#666680">%s</text></svg>`,
		escapeXML(msg))
}

// statusFields formats a lifecycle state for display. Reads the grace
// period from nsdata rather than hardcoding it, so retuning the lifecycle
// is a config change and this stays correct.
func statusFields(expires time.Time) (status, color, daysLine string) {
	now := time.Now()
	grace := nsdata.GetGracePeriod()
	switch {
	case now.Before(expires):
		return "VALID", "#4ade80", ufmt.Sprintf("%d days left", int64(expires.Sub(now)/(24*time.Hour)))
	case now.Before(expires.Add(grace)):
		left := int64(expires.Add(grace).Sub(now) / (24 * time.Hour))
		return "GRACE PERIOD", "#facc15", ufmt.Sprintf("%d days to reclaim", left)
	default:
		return "EXPIRED", "#f87171", "available to register"
	}
}

func escapeXML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	return s
}

package nslogic

import (
	"regexp"
	"strconv"
	"time"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// assertIsAdmin reads nsdata.GetAdmin() fresh every call — correct even
// immediately after a TransferAdmin, and correct for a freshly-deployed
// logic realm with no local state of its own to go stale.
//
// Note: admin authority to swap WHICH realm is trustedLogic, or to
// transfer admin itself, is deliberately NOT exposed here — those live
// only in nsdata's own admin.gno, callable solely by a direct wallet
// call from the current admin address, never proxied through logic.
// That's the one part of the system a compromised or buggy logic realm
// cannot touch.
func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != nsdata.GetAdmin() {
		panic("nslogic: restricted to project admin")
	}
}

// SetLabelPattern changes the character-validation regex for names and
// domains without a redeploy. Compiled here first (regexp.Compile, not
// MustCompile) purely to reject an admin typo before it is persisted —
// a pattern that does not compile must not reach storage, since
// validateLabel would then panic on every registration.
//
// The compiled result is deliberately NOT cached into this realm's
// local state here: currentLabelRe re-reads and recompiles whenever
// nsdata's stored string differs from the cached one, which keeps a
// freshly-swapped logic realm correct too.
func SetLabelPattern(cur realm, pattern string) {
	assertNoSend()
	assertIsAdmin(cur)
	if _, err := regexp.Compile(pattern); err != nil {
		panic("nslogic: pattern does not compile: " + err.Error())
	}
	nsdata.SetLabelPatternRecord(cross(cur), pattern)
}

func SetLabelLengthLimits(cur realm, minLen, maxLen int) {
	assertNoSend()
	assertIsAdmin(cur)
	if minLen < 1 || maxLen < minLen {
		panic("nslogic: invalid length bounds")
	}
	nsdata.SetLabelLengthRecord(cross(cur), minLen, maxLen)
}

func SetDefaultNamePrice(cur realm, price int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if price <= 0 {
		panic("nslogic: price must be positive")
	}
	setGlobal(cur, keyDefaultPrice, strconv.FormatInt(price, 10))
}

// SetTermLength / SetGracePeriod retune the lifecycle itself. Both were
// hardcoded constants in the vault until 2026-08-21 — meaning the 1-year
// term and 90-day grace could never have been changed, on a realm that
// is never redeployed. There was no reason to accept that.
// maxLifecycleDays bounds both setters. time.Duration is int64
// NANOSECONDS, so `days * 24h` overflows above ~106,751 days and wraps to
// a NEGATIVE duration — which would install a negative term and brick
// every registration and renewal in the registry. Guarding the input is
// what keeps the multiplication in range.
const maxLifecycleDays = 36500 // 100 years

func SetTermLength(cur realm, days int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if days <= 0 || days > maxLifecycleDays {
		panic("nslogic: term out of range (1..36500 days)")
	}
	term := time.Duration(days) * 24 * time.Hour
	// Keep gracePeriod <= termLength. Anchoring a renewal to the previous
	// due date is only coherent while a renewal cannot happen more than
	// one full term after it; the vault clamps forward defensively, but
	// the combination should not be reachable in the first place.
	if nsdata.GetGracePeriod() > term {
		panic("nslogic: term must be at least the current grace period")
	}
	nsdata.SetTermLengthRecord(cross(cur), term)
}

func SetGracePeriod(cur realm, days int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if days < 0 || days > maxLifecycleDays {
		panic("nslogic: grace period out of range (0..36500 days)")
	}
	grace := time.Duration(days) * 24 * time.Hour
	if grace > nsdata.GetTermLength() {
		panic("nslogic: grace period may not exceed the term length")
	}
	nsdata.SetGracePeriodRecord(cross(cur), grace)
}

// SetTokenURIBase re-points TokenURI at a different renderer, so the NFT
// artwork can be replaced without touching the vault.
func SetTokenURIBase(cur realm, base string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetTokenURIBaseRecord(cross(cur), base)
}

func SetExtraLimits(cur realm, keyLen, valueLen, entries int) {
	assertNoSend()
	assertIsAdmin(cur)
	if keyLen < 1 || valueLen < 1 || entries < 1 {
		panic("nslogic: limits must be positive")
	}
	nsdata.SetExtraLimitsRecord(cross(cur), keyLen, valueLen, entries)
}

// SetGlobal writes an arbitrary project-wide key into the vault's
// package-level extension slot — the escape hatch for global state that
// does not exist yet.
func SetGlobal(cur realm, key, value string) {
	assertNoSend()
	assertIsAdmin(cur)
	setGlobal(cur, key, value)
}

func setGlobal(cur realm, key, value string) {
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic(err)
	}
}

// SetTreasury moves the revenue-receiving role — independent of
// nsdata's TransferAdmin, same reasoning as the original build's
// admin/treasury separation.
func SetTreasury(cur realm, newTreasury address) {
	assertNoSend()
	assertIsAdmin(cur)
	if !newTreasury.IsValid() {
		panic("nslogic: invalid treasury address")
	}
	nsdata.SetTreasuryRecord(cross(cur), newTreasury)
}

// SelfAddress reports this deployed realm's own address — needed once,
// at wiring time, so admin knows what to pass to nsdata.SetTrustedLogic.
func SelfAddress(cur realm) address {
	return cur.Address()
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// RegisterDomain mints a new `*domain` — ADMIN-ONLY (2026-08-15 policy:
// domains are never sold or owned by third parties). No payment: the
// project isn't paying itself. Domains are also permanently
// non-transferable by users (see nft.gno's TransferFrom).
func RegisterDomain(cur realm, label string) {
	assertNoSend()
	assertIsAdmin(cur)
	validateLabel(label)
	caller := cur.Previous().Address()
	if err := nsdata.RegisterDomainRecord(cross(cur), label, caller, time.Now()); err != nil {
		panic(err)
	}
}

// RenewDomain extends a domain's expiry by exactly one year from its
// PREVIOUS due date, not from the payment date. No payment — domains are
// always project-owned, so this is self-service upkeep, not a sale.
// Deliberately does not call validateLabel — a tightened pattern only
// gates new registrations, never renewals of what's already registered.
func RenewDomain(cur realm, label string) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := nsdata.RenewDomainRecord(cross(cur), label, caller, time.Now()); err != nil {
		panic(err)
	}
}

// ReassignDomain moves a domain record to a new owner. ADMIN-ONLY, and
// the deliberate exception to "domains are non-transferable".
//
// It exists because domain ownership is snapshotted into the record at
// registration time, while `admin` is a rotatable role. After the
// planned EOA-to-multisig rotation, the incoming admin could not renew
// or reprice any domain the outgoing key had registered — and if the
// rotation happened *because* the old key was compromised, the attacker
// could still reprice those domains afterwards. This is the recovery
// lever for exactly that situation.
//
// Not a loophole in the non-transferability policy: that policy exists
// to stop domains reaching third parties as tradeable assets, and this
// path is reachable only by the current admin, moving a project domain
// between project-controlled addresses.
func ReassignDomain(cur realm, label string, newOwner address) {
	assertNoSend()
	assertIsAdmin(cur)
	owner := nsdata.GetDomainOwner(label)
	if err := nsdata.RawTransferNFT(cross(cur), owner, owner, newOwner, "*"+label); err != nil {
		panic(err)
	}
}

// SetDomainPricingFlat sets a single price for every name under the
// domain. Stored as an opaque string in the domain's extension slot —
// the vault has no pricing model of its own, so the model can be
// replaced by swapping this realm.
func SetDomainPricingFlat(cur realm, label string, price int64) {
	assertNoSend()
	assertDomainOwner(cur, label)
	if price <= 0 {
		panic("nslogic: price must be positive")
	}
	setDomainExtra(cur, label, keyPrice, strconv.FormatInt(price, 10))
	setDomainExtra(cur, label, keyTiers, "") // empty deletes: flat overrides tiers
}

// SetDomainPricingTiered sets price-by-name-length from a single CSV
// string, NOT []int/[]int64 slice params — vm/MsgCall (what gnokey
// maketx call and Adena's DoContract both send) only carries flat
// []string args, verified live against a slice-typed call. Format:
// "length:priceUgnot,length:priceUgnot,..." e.g. "3:50,4:20,5:10" — a
// length with no entry falls back to the domain's flat price.
func SetDomainPricingTiered(cur realm, label string, tiersCSV string) {
	assertNoSend()
	assertDomainOwner(cur, label)
	setDomainExtra(cur, label, keyTiers, normalizeTiers(tiersCSV))
}

// SetDomainField writes an arbitrary key on a domain, for whatever a
// future feature needs without a vault change.
func SetDomainField(cur realm, label, key, value string) {
	assertNoSend()
	assertDomainOwner(cur, label)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	setDomainExtra(cur, label, key, value)
}

func setDomainExtra(cur realm, label, key, value string) {
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic(err)
	}
}

func assertDomainOwner(cur realm, label string) {
	if nsdata.GetDomainOwner(label) != cur.Previous().Address() {
		panic("nslogic: restricted to domain owner")
	}
}

// FreezeDomain / UnfreezeDomain: project-only power to permanently block
// re-registration of a domain even after its grace period lapses.
func FreezeDomain(cur realm, label string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, true)
}

func UnfreezeDomain(cur realm, label string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, false)
}

package nslogic

import (
	"strings"
	"time"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// Profile field names inside a name's extension slot. The vault stores
// them as opaque strings and bounds their size; what they MEAN is this
// realm's convention, so new profile fields need no vault change.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
	keyAvatar      = "avatar"
)

// RegisterName mints `label*domain` under an existing domain. Anyone may
// call this. Minting still works while the parent domain is past its own
// due date, as long as its grace period hasn't fully lapsed and it isn't
// frozen — nsdata's RegisterNameRecord enforces that.
func RegisterName(cur realm, label, domainLabel string) {
	validateLabel(label)
	takePayment(cur, NamePrice(domainLabel, label))

	caller := cur.Previous().Address()
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, caller, time.Now(), true); err != nil {
		panic(err)
	}
}

// RenewName — same anchoring rule as RenewDomain: extends from the
// previous due date, not from the payment date. Deliberately does not
// call validateLabel — an already-registered name must keep renewing
// under whatever pattern was in force when it was minted.
func RenewName(cur realm, label, domainLabel string) {
	takePayment(cur, NamePrice(domainLabel, label))

	caller := cur.Previous().Address()
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, caller, time.Now()); err != nil {
		panic(err)
	}
}

// SetProfile writes the four conventional profile fields. Each lands in
// the name's extension slot, where the vault enforces size bounds.
func SetProfile(cur realm, label, domainLabel, displayName, bio, website, avatar string) {
	assertNoSend()
	assertNameOwner(cur, label, domainLabel)
	setExtra(cur, label, domainLabel, keyDisplayName, displayName)
	setExtra(cur, label, domainLabel, keyBio, bio)
	setExtra(cur, label, domainLabel, keyWebsite, website)
	setExtra(cur, label, domainLabel, keyAvatar, avatar)
}

// SetNameField writes a single arbitrary key — cross-chain addresses and
// anything else a future feature needs, with no vault change required.
// Keys used by this realm's own machinery are reserved.
func SetNameField(cur realm, label, domainLabel, key, value string) {
	assertNoSend()
	assertNameOwner(cur, label, domainLabel)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	setExtra(cur, label, domainLabel, key, value)
}

func setExtra(cur realm, label, domainLabel, key, value string) {
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic(err)
	}
}

func assertNameOwner(cur realm, label, domainLabel string) {
	if nsdata.GetNameOwner(label, domainLabel) != cur.Previous().Address() {
		panic("nslogic: restricted to name owner")
	}
}

// SetPrimaryName lets a wallet explicitly choose (and later change) which
// of its names is used for reverse resolution.
func SetPrimaryName(cur realm, label, domainLabel string) {
	assertNoSend()
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if err := nsdata.SetPrimaryRecord(cross(cur), caller, label, domainLabel); err != nil {
		panic(err)
	}
}

func FreezeName(cur realm, label, domainLabel string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
}

func UnfreezeName(cur realm, label, domainLabel string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, false)
}

// -- resolution --

func ResolveName(label, domainLabel string) address {
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: name is expired")
	}
	return nsdata.GetNameOwner(label, domainLabel)
}

// ResolveAddress performs reverse resolution: address -> name.
//
// It must verify the ownership it is asserting, not merely that the
// pointed-at name exists and is unexpired. nsdata's `primary` tree is a
// record of what an address last SELECTED, not proof of what it still
// owns — and although nsdata now clears the pointer on transfer and
// reclaim, this check is the half that lives in the swappable realm and
// therefore stays correct even against pointers written by an older
// version of the logic. Without it, an address that sold or lost a name
// kept reverse-resolving to it, impersonating the new owner.
func ResolveAddress(addr address) string {
	tid := nsdata.GetPrimary(addr)
	if tid == "" {
		return ""
	}
	label, domainLabel := splitTokenID(tid)
	if !nsdata.IsNameValid(label, domainLabel) {
		return ""
	}
	if nsdata.GetNameOwner(label, domainLabel) != addr {
		return ""
	}
	return tid
}

// splitTokenID splits a `label*domain` token ID.
func splitTokenID(tid string) (label, domainLabel string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

package nslogic

import (
	"strings"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// This realm only exposes the WRITE side of the GRC-721 surface. Reads
// (BalanceOf, OwnerOf, TokenURI, GetApproved, IsApprovedForAll, and
// every listing/status/profile query) have no authorization check to
// perform and are served directly by nsdata — no reason to duplicate
// them here.

func isDomainToken(tid string) bool {
	return strings.HasPrefix(tid, "*")
}

// isTokenValid checks the underlying domain/name's expiry via nsdata's
// own validity reads — the anti-scam pattern (an expired name must not
// be sellable) enforced at the transfer boundary, not just at read time.
func isTokenValid(tid string) bool {
	if isDomainToken(tid) {
		return nsdata.IsDomainValid(tid[1:])
	}
	label, domainLabel := splitTokenID(tid)
	return nsdata.IsNameValid(label, domainLabel)
}

func Approve(cur realm, to address, tid string) {
	assertNoSend()
	if isDomainToken(tid) {
		panic("nslogic: domains are project-owned and non-transferable")
	}
	if !isTokenValid(tid) {
		panic("nslogic: cannot approve an expired token")
	}
	caller := cur.Previous().Address()
	if err := nsdata.RawApprove(cross(cur), caller, to, tid); err != nil {
		panic(err)
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := nsdata.RawSetApprovalForAll(cross(cur), caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom / SafeTransferFrom are the actual enforcement point for
// both (a) the anti-scam pattern — blocking transfer of an expired token
// closes off third-party marketplace sales without blocking the owner's
// own ability to reclaim by renewing (renewal never goes through these)
// — and (b) the domains-are-never-transferable policy: blocking it here,
// not just at RegisterDomain, is what actually closes the loophole.
// (ReassignDomain in domain.gno is the deliberate admin-only exception;
// see its comment.)
func TransferFrom(cur realm, from, to address, tid string) {
	assertNoSend()
	if isDomainToken(tid) {
		panic("nslogic: domains are project-owned and non-transferable")
	}
	if !isTokenValid(tid) {
		panic("nslogic: cannot transfer an expired token")
	}
	label, domainLabel := splitTokenID(tid)
	caller := cur.Previous().Address()
	// A free-tier record has no GRC-721 token to move, so the token-layer
	// transfer would fail; the vault exposes a record-only path for it.
	if !nsdata.IsNameNFT(label, domainLabel) {
		if caller != from || nsdata.GetNameOwner(label, domainLabel) != caller {
			panic("nslogic: restricted to name owner")
		}
		if err := nsdata.TransferRecordOwner(cross(cur), label, domainLabel, to); err != nil {
			panic(err)
		}
		return
	}
	if err := nsdata.RawTransferNFT(cross(cur), caller, from, to, tid); err != nil {
		panic(err)
	}
}

// nsdata only exposes one raw transfer primitive (RawTransferNFT, backed
// by grc721's plain TransferFrom) — the safe-receiver-interface check
// grc721's SafeTransferFrom adds doesn't carry much weight for a
// name-service NFT, so both entry points converge on the same path here.
func SafeTransferFrom(cur realm, from, to address, tid string) {
	TransferFrom(cur, from, to, tid)
}

package nslogic

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// takePayment verifies the attached send-envelope covers `price` ugnot,
// forwards the price to the treasury, and refunds any overpayment to the
// caller in the same transaction. Nothing is ever retained: every ugnot
// that arrives leaves again, as either payment or refund.
//
// It used to take a `beneficiary` and split the price fee/remainder,
// routing the remainder to treasury only while `beneficiary == admin`.
// That comparison was a proxy for "is this a project-owned domain", and
// it silently broke the moment `admin` rotated — the planned EOA-to-
// multisig step — because a domain's owner is frozen into its record at
// registration time. After a rotation, every registration's remainder
// would have been paid to the retired key instead of the treasury, with
// no error and no log line.
//
// The heuristic is gone rather than patched. Domains are admin-only to
// create and permanently non-transferable, so every domain is
// project-owned by construction and 100% of every payment belongs to the
// treasury. `platformFeeBps` stays in nsdata's config for a future logic
// realm that reintroduces third-party domain ownership; reinstating the
// split is then a logic-realm swap, not a migration.
func takePayment(cur realm, price int64) {
	if !cur.Previous().IsUserCall() {
		panic("nslogic: only direct wallet calls may attach payment")
	}
	caller := cur.Previous().Address()
	sent := unsafe.OriginSend()
	assertOnlyUgnot(sent)

	paid := sent.AmountOf(ugnot)
	if paid < price {
		panic(ufmt.Sprintf("nslogic: insufficient payment: need %d ugnot, got %d", price, paid))
	}
	excess := paid - price

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	pkgAddr := cur.Address()
	if price > 0 {
		b.SendCoins(pkgAddr, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, price)})
	}
	if excess > 0 {
		b.SendCoins(pkgAddr, caller, chain.Coins{chain.NewCoin(ugnot, excess)})
	}
}

// assertOnlyUgnot rejects any other denomination outright. Only the
// ugnot amount was ever accounted for, and neither realm has a
// withdrawal path, so a foreign coin sent alongside a payment would have
// been stranded in this realm's address permanently. Refusing the whole
// transaction is simpler than sweeping it back and keeps the
// "this realm never retains funds" invariant absolute.
func assertOnlyUgnot(sent chain.Coins) {
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nslogic: only ugnot is accepted, got: " + c.Denom)
		}
	}
}

// assertNoSend guards every entry point that has no price. Without it,
// coins attached to a free call (a renewal of a project domain, a
// profile edit, an admin setter) would land in this realm's address with
// no way back out.
func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("nslogic: this function takes no payment; do not attach coins")
	}
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// Pricing lives here, not in the vault. The vault stores the numbers as
// opaque strings in a domain's extension slot and has no opinion about
// what they mean — which is what lets the whole pricing model be
// replaced by swapping this realm, rather than being frozen forever at
// deployment.
//
// Domain extension keys:
//   "price" — flat price in ugnot, applied when no tier matches
//   "tiers" — "length:price,length:price,…" e.g. "3:50000000,4:20000000"
// Global key:
//   "defaultPrice" — fallback when a domain sets no price of its own
const (
	keyPrice        = "price"
	keyTiers        = "tiers"
	keyDefaultPrice = "defaultPrice"

	fallbackPrice = int64(1_000_000)
	maxTiers      = 64
)

// NamePrice resolves what a given label costs under a given domain:
// a length-tier match if one exists, else the domain's flat price, else
// the global default.
func NamePrice(domainLabel, label string) int64 {
	if tiers := nsdata.GetDomainExtra(domainLabel, keyTiers); tiers != "" {
		if p, ok := lookupTier(tiers, len(label)); ok {
			return p
		}
	}
	if flat := nsdata.GetDomainExtra(domainLabel, keyPrice); flat != "" {
		if v, err := strconv.ParseInt(flat, 10, 64); err == nil && v > 0 {
			return v
		}
	}
	return DefaultPrice()
}

func DefaultPrice() int64 {
	if v := nsdata.GetGlobal(keyDefaultPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p > 0 {
			return p
		}
	}
	return fallbackPrice
}

func lookupTier(tiersCSV string, length int) (int64, bool) {
	want := strconv.Itoa(length)
	for _, pair := range strings.Split(tiersCSV, ",") {
		parts := strings.Split(strings.TrimSpace(pair), ":")
		if len(parts) != 2 || strings.TrimSpace(parts[0]) != want {
			continue
		}
		if p, err := strconv.ParseInt(strings.TrimSpace(parts[1]), 10, 64); err == nil && p > 0 {
			return p, true
		}
	}
	return 0, false
}

// normalizeTiers validates a tier string before it is stored. Parsing on
// write means a malformed string can never reach storage and break every
// later price lookup.
func normalizeTiers(tiersCSV string) string {
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(tiersCSV, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.Split(pair, ":")
		if len(parts) != 2 {
			panic("nslogic: bad tier format, want length:price")
		}
		lenStr := strings.TrimSpace(parts[0])
		n, err := strconv.Atoi(lenStr)
		if err != nil || n <= 0 {
			panic("nslogic: bad tier length: " + lenStr)
		}
		priceStr := strings.TrimSpace(parts[1])
		p, err := strconv.ParseInt(priceStr, 10, 64)
		if err != nil || p <= 0 {
			panic("nslogic: bad tier price: " + priceStr)
		}
		if seen[lenStr] {
			panic("nslogic: duplicate tier length: " + lenStr)
		}
		seen[lenStr] = true
		out = append(out, lenStr+":"+priceStr)
		if len(out) > maxTiers {
			panic("nslogic: too many tiers")
		}
	}
	if len(out) == 0 {
		panic("nslogic: no valid tiers given")
	}
	return strings.Join(out, ",")
}

// Package nslogic is the swappable "business rules" half of the split
// (NOTES.md §9t). It holds every piece of policy that might reasonably
// change — pricing, character validation, payment/refund, freeze rules,
// transfer restrictions — and no persistent records of its own.
//
// Every mutation here ends by calling into nsdata's narrow Record/Raw
// API via cross(cur). nsdata trusts whichever address is currently wired
// up as trustedLogic to have done its own authorization checks
// correctly, so THIS realm is where "is the caller allowed to do this"
// actually lives. If a bug is found here, admin deploys a fixed nslogic
// and re-points nsdata.SetTrustedLogic at it — no data migration,
// records and config untouched.
//
// Deliberately reads config fresh from nsdata on every call rather than
// caching it. The one thing that cannot be read fresh is a COMPILED
// regex — avl trees store the pattern string, not the compiled object —
// so that one value is cached, and the cache is validated against
// nsdata on every use (see currentLabelRe).
package nslogic

import (
	"regexp"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

const (
	ugnot    = "ugnot"
	bpsDenom = 10_000
)

// Cached compile of nsdata's stored labelPattern. Both fields are
// written together and only by currentLabelRe.
var (
	labelPattern string
	reLabel      *regexp.Regexp
)

// Structural, not admin-tunable, so it stays a local constant: anything
// shaped like a real gno.land address is refused as a label, so a name
// can never be mistaken for a raw wallet address in a UI.
var reAddressLookalike = regexp.MustCompile(`^g1[a-z0-9]{20,38}$`)

// currentLabelRe returns the compiled form of whatever pattern nsdata
// currently stores, recompiling only when the string has changed.
//
// This replaces a snapshot taken once in init(). The snapshot was a
// silent-divergence bug: nsdata holds the pattern string, this realm
// held a compiled copy, and nothing kept them in sync across a
// logic-realm swap. A replacement nslogic deployed before the last
// SetLabelPattern would enforce its own stale pattern while every
// reader — GetLabelPattern, the error message, the UI — reported
// nsdata's newer one, so registrations would fail against a rule nobody
// could see. Reading through here on every call makes that impossible
// by construction.
func currentLabelRe() *regexp.Regexp {
	p := nsdata.GetLabelPattern()
	if reLabel == nil || p != labelPattern {
		compiled, err := regexp.Compile(p)
		if err != nil {
			panic("nslogic: stored label pattern does not compile: " + err.Error())
		}
		labelPattern, reLabel = p, compiled
	}
	return reLabel
}

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// validateLabel — same policy as the original single-realm build (see
// NOTES.md for the ENS/Starname/r/sys/users research behind it). Length
// bounds and the character pattern are both read from nsdata, so they
// survive a swap of this realm.
//
// Call sites, and why: RegisterName/RegisterDomain only (both the
// first-ever mint AND reclaiming a past-grace slot — a reclaim is a
// genuine new mint with a new owner). RenewName/RenewDomain deliberately
// do NOT call this — an already-registered name must keep renewing under
// whatever pattern was in force when it was minted, even after the admin
// tightens the pattern later.
func validateLabel(label string) {
	minLen, maxLen := nsdata.GetLabelLength()
	if len(label) < minLen || len(label) > maxLen {
		panic(ufmt.Sprintf("nslogic: label must be %d-%d characters", minLen, maxLen))
	}
	// Structural invariant, enforced regardless of what the admin-tunable
	// pattern happens to allow: "*" is the separator in both the token ID
	// (label*domain) and nsdata's storage key (domain*label). A label or
	// domain containing one would make those encodings ambiguous and let
	// two different names collide onto a single record.
	if strings.Contains(label, "*") {
		panic("nslogic: label may not contain '*'")
	}
	if !currentLabelRe().MatchString(label) {
		panic("nslogic: label doesn't match the current allowed pattern (see nsdata.GetLabelPattern)")
	}
	if reAddressLookalike.MatchString(label) {
		panic("nslogic: label looks like a wallet address, not allowed")
	}
}

package nslogic

import (
	"regexp"
	"strconv"
	"time"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// assertIsAdmin reads nsdata.GetAdmin() fresh every call — correct even
// immediately after a TransferAdmin, and correct for a freshly-deployed
// logic realm with no local state of its own to go stale.
//
// Note: admin authority to swap WHICH realm is trustedLogic, or to
// transfer admin itself, is deliberately NOT exposed here — those live
// only in nsdata's own admin.gno, callable solely by a direct wallet
// call from the current admin address, never proxied through logic.
// That's the one part of the system a compromised or buggy logic realm
// cannot touch.
func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != nsdata.GetAdmin() {
		panic("nslogic: restricted to project admin")
	}
}

// SetLabelPattern changes the character-validation regex for names and
// domains without a redeploy. Compiled here first (regexp.Compile, not
// MustCompile) purely to reject an admin typo before it is persisted —
// a pattern that does not compile must not reach storage, since
// validateLabel would then panic on every registration.
//
// The compiled result is deliberately NOT cached into this realm's
// local state here: currentLabelRe re-reads and recompiles whenever
// nsdata's stored string differs from the cached one, which keeps a
// freshly-swapped logic realm correct too.
func SetLabelPattern(cur realm, pattern string) {
	assertNoSend()
	assertIsAdmin(cur)
	if _, err := regexp.Compile(pattern); err != nil {
		panic("nslogic: pattern does not compile: " + err.Error())
	}
	nsdata.SetLabelPatternRecord(cross(cur), pattern)
}

func SetLabelLengthLimits(cur realm, minLen, maxLen int) {
	assertNoSend()
	assertIsAdmin(cur)
	if minLen < 1 || maxLen < minLen {
		panic("nslogic: invalid length bounds")
	}
	nsdata.SetLabelLengthRecord(cross(cur), minLen, maxLen)
}

// SetDefaultNamePrice sets the fallback price in micro-USD, used by any
// domain that has not set its own base.
func SetDefaultNamePrice(cur realm, microUsd int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if microUsd < 0 {
		panic("nslogic: price cannot be negative")
	}
	setGlobal(cur, keyDefaultPrice, strconv.FormatInt(microUsd, 10))
}

// SetUsdRate records how many ugnot one USD buys — the bridge between
// the USD price list and settlement on this chain.
//
// It is a MANUAL rate, not a market feed: it sits where it was last
// written. A stale rate during a sharp move sells names at the wrong
// price, and no amount of contract logic fixes that — keeping it current
// is an operational duty. Isolated as one global so a future logic realm
// can swap in a real oracle without touching the vault or restating a
// single price.
func SetUsdRate(cur realm, ugnotPerUsd int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if ugnotPerUsd <= 0 {
		panic("nslogic: rate must be positive")
	}
	setGlobal(cur, keyRate, strconv.FormatInt(ugnotPerUsd, 10))
}

// SetTermLength / SetGracePeriod retune the lifecycle itself. Both were
// hardcoded constants in the vault until 2026-08-21 — meaning the 1-year
// term and 90-day grace could never have been changed, on a realm that
// is never redeployed. There was no reason to accept that.
// maxLifecycleDays bounds both setters. time.Duration is int64
// NANOSECONDS, so `days * 24h` overflows above ~106,751 days and wraps to
// a NEGATIVE duration — which would install a negative term and brick
// every registration and renewal in the registry. Guarding the input is
// what keeps the multiplication in range.
const maxLifecycleDays = 36500 // 100 years

func SetTermLength(cur realm, days int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if days <= 0 || days > maxLifecycleDays {
		panic("nslogic: term out of range (1..36500 days)")
	}
	term := time.Duration(days) * 24 * time.Hour
	// Keep gracePeriod <= termLength. Anchoring a renewal to the previous
	// due date is only coherent while a renewal cannot happen more than
	// one full term after it; the vault clamps forward defensively, but
	// the combination should not be reachable in the first place.
	if nsdata.GetGracePeriod() > term {
		panic("nslogic: term must be at least the current grace period")
	}
	nsdata.SetTermLengthRecord(cross(cur), term)
}

func SetGracePeriod(cur realm, days int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if days < 0 || days > maxLifecycleDays {
		panic("nslogic: grace period out of range (0..36500 days)")
	}
	grace := time.Duration(days) * 24 * time.Hour
	if grace > nsdata.GetTermLength() {
		panic("nslogic: grace period may not exceed the term length")
	}
	nsdata.SetGracePeriodRecord(cross(cur), grace)
}

// SetTokenURIBase re-points TokenURI at a different renderer, so the NFT
// artwork can be replaced without touching the vault.
func SetTokenURIBase(cur realm, base string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetTokenURIBaseRecord(cross(cur), base)
}

func SetExtraLimits(cur realm, keyLen, valueLen, entries int) {
	assertNoSend()
	assertIsAdmin(cur)
	if keyLen < 1 || valueLen < 1 || entries < 1 {
		panic("nslogic: limits must be positive")
	}
	nsdata.SetExtraLimitsRecord(cross(cur), keyLen, valueLen, entries)
}

// SetGlobal writes an arbitrary project-wide key into the vault's
// package-level extension slot — the escape hatch for global state that
// does not exist yet.
func SetGlobal(cur realm, key, value string) {
	assertNoSend()
	assertIsAdmin(cur)
	setGlobal(cur, key, value)
}

func setGlobal(cur realm, key, value string) {
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic(err)
	}
}

// SetTreasury moves the revenue-receiving role — independent of
// nsdata's TransferAdmin, same reasoning as the original build's
// admin/treasury separation.
func SetTreasury(cur realm, newTreasury address) {
	assertNoSend()
	assertIsAdmin(cur)
	if !newTreasury.IsValid() {
		panic("nslogic: invalid treasury address")
	}
	nsdata.SetTreasuryRecord(cross(cur), newTreasury)
}

// SelfAddress reports this deployed realm's own address — needed once,
// at wiring time, so admin knows what to pass to nsdata.SetTrustedLogic.
func SelfAddress(cur realm) address {
	return cur.Address()
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// RegisterDomain mints a new `*domain` — ADMIN-ONLY (2026-08-15 policy:
// domains are never sold or owned by third parties). No payment: the
// project isn't paying itself. Domains are also permanently
// non-transferable by users (see nft.gno's TransferFrom).
func RegisterDomain(cur realm, label string) {
	assertNoSend()
	assertIsAdmin(cur)
	validateLabel(label)
	caller := cur.Previous().Address()
	if err := nsdata.RegisterDomainRecord(cross(cur), label, caller, time.Now()); err != nil {
		panic(err)
	}
}

// RenewDomain extends a domain's expiry by exactly one year from its
// PREVIOUS due date, not from the payment date. No payment — domains are
// always project-owned, so this is self-service upkeep, not a sale.
// Deliberately does not call validateLabel — a tightened pattern only
// gates new registrations, never renewals of what's already registered.
func RenewDomain(cur realm, label string) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := nsdata.RenewDomainRecord(cross(cur), label, caller, time.Now()); err != nil {
		panic(err)
	}
}

// ReassignDomain moves a domain record to a new owner. ADMIN-ONLY, and
// the deliberate exception to "domains are non-transferable".
//
// It exists because domain ownership is snapshotted into the record at
// registration time, while `admin` is a rotatable role. After the
// planned EOA-to-multisig rotation, the incoming admin could not renew
// or reprice any domain the outgoing key had registered — and if the
// rotation happened *because* the old key was compromised, the attacker
// could still reprice those domains afterwards. This is the recovery
// lever for exactly that situation.
//
// Not a loophole in the non-transferability policy: that policy exists
// to stop domains reaching third parties as tradeable assets, and this
// path is reachable only by the current admin, moving a project domain
// between project-controlled addresses.
func ReassignDomain(cur realm, label string, newOwner address) {
	assertNoSend()
	assertIsAdmin(cur)
	owner := nsdata.GetDomainOwner(label)
	if err := nsdata.RawTransferNFT(cross(cur), owner, owner, newOwner, "*"+label); err != nil {
		panic(err)
	}
}

// -- pricing controls (admin) --
//
// Every amount here is MICRO-USD (1 USD = 1_000_000). Nothing is priced
// in the chain token; ugnot is derived at payment time from the stored
// rate, so a second settlement token later is a second rate rather than
// a second price list.

// SetDomainOpen enables or disables registration of new names under a
// domain. Existing names are untouched: closing a domain stops new
// mints, it does not seize anything already held.
func SetDomainOpen(cur realm, label string, open bool) {
	assertNoSend()
	assertIsAdmin(cur)
	v := "1"
	if !open {
		v = "0"
	}
	setDomainExtra(cur, label, keyOpen, v)
}

// SetDomainBasePrice sets the domain's base price in micro-USD. Every
// "%N" rule under the domain is relative to this, so one call reprices
// the whole domain.
func SetDomainBasePrice(cur realm, label string, microUsd int64) {
	assertNoSend()
	assertIsAdmin(cur)
	if microUsd < 0 {
		panic("nslogic: price cannot be negative")
	}
	setDomainExtra(cur, label, keyPrice, strconv.FormatInt(microUsd, 10))
}

// SetDomainLengthRules prices by label length: "3:2000000,4:%150,5:0"
// means 3-char names cost $2.00, 4-char names cost 150% of the domain
// base, and 5-char names are free.
func SetDomainLengthRules(cur realm, label, rules string) {
	assertNoSend()
	assertIsAdmin(cur)
	setDomainExtra(cur, label, keyLens, normalizeRules(rules, true))
}

// SetDomainNameOverrides prices specific labels: "420:5000000,gm:%500".
// Highest precedence — this beats length rules and the base.
func SetDomainNameOverrides(cur realm, label, rules string) {
	assertNoSend()
	assertIsAdmin(cur)
	setDomainExtra(cur, label, keyNames, normalizeRules(rules, false))
}

// SetDomainField writes an arbitrary key on a domain, for whatever a
// future feature needs without a vault change.
func SetDomainField(cur realm, label, key, value string) {
	assertNoSend()
	assertIsAdmin(cur)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	setDomainExtra(cur, label, key, value)
}

func setDomainExtra(cur realm, label, key, value string) {
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic(err)
	}
}

// FreezeDomain / UnfreezeDomain: project-only power to permanently block
// re-registration of a domain even after its grace period lapses.
func FreezeDomain(cur realm, label string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, true)
}

func UnfreezeDomain(cur realm, label string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, false)
}

package nslogic

import (
	"strings"
	"time"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// Profile field names inside a name's extension slot. The vault stores
// them as opaque strings and bounds their size; what they MEAN is this
// realm's convention, so new profile fields need no vault change.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
	keyAvatar      = "avatar"
)

// RegisterName mints `label*domain` under an existing domain. Anyone may
// call this. Minting still works while the parent domain is past its own
// due date, as long as its grace period hasn't fully lapsed and it isn't
// frozen — nsdata's RegisterNameRecord enforces that.
func RegisterName(cur realm, label, domainLabel string) {
	validateLabel(label)
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	takePayment(cur, NamePrice(domainLabel, label))

	caller := cur.Previous().Address()
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, caller, time.Now(), true); err != nil {
		panic(err)
	}
}

// RenewName — same anchoring rule as RenewDomain: extends from the
// previous due date, not from the payment date. Deliberately does not
// call validateLabel — an already-registered name must keep renewing
// under whatever pattern was in force when it was minted.
func RenewName(cur realm, label, domainLabel string) {
	takePayment(cur, NamePrice(domainLabel, label))

	caller := cur.Previous().Address()
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, caller, time.Now()); err != nil {
		panic(err)
	}
}

// SetProfile writes the four conventional profile fields. Each lands in
// the name's extension slot, where the vault enforces size bounds.
func SetProfile(cur realm, label, domainLabel, displayName, bio, website, avatar string) {
	assertNoSend()
	assertNameOwner(cur, label, domainLabel)
	setExtra(cur, label, domainLabel, keyDisplayName, displayName)
	setExtra(cur, label, domainLabel, keyBio, bio)
	setExtra(cur, label, domainLabel, keyWebsite, website)
	setExtra(cur, label, domainLabel, keyAvatar, avatar)
}

// SetNameField writes a single arbitrary key — cross-chain addresses and
// anything else a future feature needs, with no vault change required.
// Keys used by this realm's own machinery are reserved.
func SetNameField(cur realm, label, domainLabel, key, value string) {
	assertNoSend()
	assertNameOwner(cur, label, domainLabel)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	setExtra(cur, label, domainLabel, key, value)
}

func setExtra(cur realm, label, domainLabel, key, value string) {
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic(err)
	}
}

func assertNameOwner(cur realm, label, domainLabel string) {
	if nsdata.GetNameOwner(label, domainLabel) != cur.Previous().Address() {
		panic("nslogic: restricted to name owner")
	}
}

// SetPrimaryName lets a wallet explicitly choose (and later change) which
// of its names is used for reverse resolution.
func SetPrimaryName(cur realm, label, domainLabel string) {
	assertNoSend()
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if err := nsdata.SetPrimaryRecord(cross(cur), caller, label, domainLabel); err != nil {
		panic(err)
	}
}

func FreezeName(cur realm, label, domainLabel string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
}

func UnfreezeName(cur realm, label, domainLabel string) {
	assertNoSend()
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, false)
}

// -- resolution --

func ResolveName(label, domainLabel string) address {
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: name is expired")
	}
	return nsdata.GetNameOwner(label, domainLabel)
}

// ResolveAddress performs reverse resolution: address -> name.
//
// It must verify the ownership it is asserting, not merely that the
// pointed-at name exists and is unexpired. nsdata's `primary` tree is a
// record of what an address last SELECTED, not proof of what it still
// owns — and although nsdata now clears the pointer on transfer and
// reclaim, this check is the half that lives in the swappable realm and
// therefore stays correct even against pointers written by an older
// version of the logic. Without it, an address that sold or lost a name
// kept reverse-resolving to it, impersonating the new owner.
func ResolveAddress(addr address) string {
	tid := nsdata.GetPrimary(addr)
	if tid == "" {
		return ""
	}
	label, domainLabel := splitTokenID(tid)
	if !nsdata.IsNameValid(label, domainLabel) {
		return ""
	}
	if nsdata.GetNameOwner(label, domainLabel) != addr {
		return ""
	}
	return tid
}

// splitTokenID splits a `label*domain` token ID.
func splitTokenID(tid string) (label, domainLabel string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

package nslogic

import (
	"strings"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// This realm only exposes the WRITE side of the GRC-721 surface. Reads
// (BalanceOf, OwnerOf, TokenURI, GetApproved, IsApprovedForAll, and
// every listing/status/profile query) have no authorization check to
// perform and are served directly by nsdata — no reason to duplicate
// them here.

func isDomainToken(tid string) bool {
	return strings.HasPrefix(tid, "*")
}

// isTokenValid checks the underlying domain/name's expiry via nsdata's
// own validity reads — the anti-scam pattern (an expired name must not
// be sellable) enforced at the transfer boundary, not just at read time.
func isTokenValid(tid string) bool {
	if isDomainToken(tid) {
		return nsdata.IsDomainValid(tid[1:])
	}
	label, domainLabel := splitTokenID(tid)
	return nsdata.IsNameValid(label, domainLabel)
}

func Approve(cur realm, to address, tid string) {
	assertNoSend()
	if isDomainToken(tid) {
		panic("nslogic: domains are project-owned and non-transferable")
	}
	if !isTokenValid(tid) {
		panic("nslogic: cannot approve an expired token")
	}
	caller := cur.Previous().Address()
	if err := nsdata.RawApprove(cross(cur), caller, to, tid); err != nil {
		panic(err)
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := nsdata.RawSetApprovalForAll(cross(cur), caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom / SafeTransferFrom are the actual enforcement point for
// both (a) the anti-scam pattern — blocking transfer of an expired token
// closes off third-party marketplace sales without blocking the owner's
// own ability to reclaim by renewing (renewal never goes through these)
// — and (b) the domains-are-never-transferable policy: blocking it here,
// not just at RegisterDomain, is what actually closes the loophole.
// (ReassignDomain in domain.gno is the deliberate admin-only exception;
// see its comment.)
func TransferFrom(cur realm, from, to address, tid string) {
	assertNoSend()
	if isDomainToken(tid) {
		panic("nslogic: domains are project-owned and non-transferable")
	}
	if !isTokenValid(tid) {
		panic("nslogic: cannot transfer an expired token")
	}
	label, domainLabel := splitTokenID(tid)
	caller := cur.Previous().Address()
	// A free-tier record has no GRC-721 token to move, so the token-layer
	// transfer would fail; the vault exposes a record-only path for it.
	if !nsdata.IsNameNFT(label, domainLabel) {
		if caller != from || nsdata.GetNameOwner(label, domainLabel) != caller {
			panic("nslogic: restricted to name owner")
		}
		if err := nsdata.TransferRecordOwner(cross(cur), label, domainLabel, to); err != nil {
			panic(err)
		}
		return
	}
	if err := nsdata.RawTransferNFT(cross(cur), caller, from, to, tid); err != nil {
		panic(err)
	}
}

// nsdata only exposes one raw transfer primitive (RawTransferNFT, backed
// by grc721's plain TransferFrom) — the safe-receiver-interface check
// grc721's SafeTransferFrom adds doesn't carry much weight for a
// name-service NFT, so both entry points converge on the same path here.
func SafeTransferFrom(cur realm, from, to address, tid string) {
	TransferFrom(cur, from, to, tid)
}

package nslogic

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// takePayment verifies the attached send-envelope covers `price` ugnot,
// forwards the price to the treasury, and refunds any overpayment to the
// caller in the same transaction. Nothing is ever retained: every ugnot
// that arrives leaves again, as either payment or refund.
//
// It used to take a `beneficiary` and split the price fee/remainder,
// routing the remainder to treasury only while `beneficiary == admin`.
// That comparison was a proxy for "is this a project-owned domain", and
// it silently broke the moment `admin` rotated — the planned EOA-to-
// multisig step — because a domain's owner is frozen into its record at
// registration time. After a rotation, every registration's remainder
// would have been paid to the retired key instead of the treasury, with
// no error and no log line.
//
// The heuristic is gone rather than patched. Domains are admin-only to
// create and permanently non-transferable, so every domain is
// project-owned by construction and 100% of every payment belongs to the
// treasury. `platformFeeBps` stays in nsdata's config for a future logic
// realm that reintroduces third-party domain ownership; reinstating the
// split is then a logic-realm swap, not a migration.
func takePayment(cur realm, price int64) {
	if !cur.Previous().IsUserCall() {
		panic("nslogic: only direct wallet calls may attach payment")
	}
	caller := cur.Previous().Address()
	sent := unsafe.OriginSend()
	assertOnlyUgnot(sent)

	paid := sent.AmountOf(ugnot)
	if paid < price {
		panic(ufmt.Sprintf("nslogic: insufficient payment: need %d ugnot, got %d", price, paid))
	}
	excess := paid - price

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	pkgAddr := cur.Address()
	if price > 0 {
		b.SendCoins(pkgAddr, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, price)})
	}
	if excess > 0 {
		b.SendCoins(pkgAddr, caller, chain.Coins{chain.NewCoin(ugnot, excess)})
	}
}

// assertOnlyUgnot rejects any other denomination outright. Only the
// ugnot amount was ever accounted for, and neither realm has a
// withdrawal path, so a foreign coin sent alongside a payment would have
// been stranded in this realm's address permanently. Refusing the whole
// transaction is simpler than sweeping it back and keeps the
// "this realm never retains funds" invariant absolute.
func assertOnlyUgnot(sent chain.Coins) {
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nslogic: only ugnot is accepted, got: " + c.Denom)
		}
	}
}

// assertNoSend guards every entry point that has no price. Without it,
// coins attached to a free call (a renewal of a project domain, a
// profile edit, an admin setter) would land in this realm's address with
// no way back out.
func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("nslogic: this function takes no payment; do not attach coins")
	}
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// Pricing lives here, not in the vault. The vault stores numbers as
// opaque strings and has no opinion about what they mean, so the whole
// model can be replaced by swapping this realm.
//
// PRICES ARE DENOMINATED IN USD, held as MICRO-USD (1 USD = 1_000_000)
// so fractions of a cent are expressible — a name that costs about a
// gumball needs that. Nothing is stored in ugnot: the chain's token is
// just the settlement rail, converted at payment time from a stored
// rate. Accepting a second token later is then only a second rate, not
// a second price list.
//
// PRECEDENCE — most specific wins:
//
//   1. per-name override      (keyNames: "420:5000000,gm:%500")
//   2. per-length rule        (keyLens:  "3:2000000,4:%150,5:0")
//   3. domain base price      (keyPrice: "500000"  = $0.50)
//   4. global default         (global keyDefaultPrice)
//
// A rule value is either an absolute micro-USD amount or "%N", meaning N
// percent of that domain's base — so repricing a domain once carries
// every relative rule under it. "0" means free, which is how giveaway
// tiers are expressed: "all five-character names under *pleb are free"
// is just a length rule resolving to zero.
//
// Rules are stored as CSV in ONE key each rather than one key per rule.
// The vault caps extension keys at 32 bytes and 24 entries per record; a
// key like "nm:somelongname" breaks the first and a few dozen premium
// names break the second. Two CSV keys sidestep both.
const (
	keyPrice        = "price" // domain base, micro-USD
	keyLens         = "len"   // length rules
	keyNames        = "nm"    // per-name overrides
	keyOpen         = "open"  // "0" closes the domain to new names
	keyDefaultPrice = "defaultPrice"
	keyRate         = "rateUgnotPerUsd" // ugnot equal to 1 USD

	microUSD          = int64(1_000_000)
	fallbackPriceUSD  = int64(500_000) // $0.50
	// TESTNET PEG: $0.069 per GNOT, so 1 USD = 1/0.069 GNOT = 14.492753
	// GNOT = 14_492_753 ugnot. Deliberately a fixed number while we are on
	// a testnet whose token has no market price at all -- a "real" rate
	// there would be fiction dressed as precision. Replaced with a genuine
	// conversion before mainnet; tracked in MAINNET.md.
	fallbackRate      = int64(14_492_753)
	maxRules          = 64
)

// DomainOpen reports whether names may currently be registered under a
// domain. An absent key means open — a domain created before this
// existed must not silently close.
func DomainOpen(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyOpen) != "0"
}

// -- USD side --

func DefaultPriceUSD() int64 {
	if v := nsdata.GetGlobal(keyDefaultPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return fallbackPriceUSD
}

func DomainBasePriceUSD(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return DefaultPriceUSD()
}

// NamePriceUSD resolves the four inputs in precedence order and returns
// micro-USD. This is the authoritative price; ugnot is derived from it.
func NamePriceUSD(domainLabel, label string) int64 {
	base := DomainBasePriceUSD(domainLabel)
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyNames), label); ok {
		return applyRule(v, base)
	}
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyLens), strconv.Itoa(len(label))); ok {
		return applyRule(v, base)
	}
	return base
}

// -- settlement side --

// RateUgnotPerUsd is how many ugnot one USD buys.
//
// This is a MANUALLY MAINTAINED rate, not a market oracle: an admin
// writes it and it sits there until rewritten. That is a real
// operational hazard — a stale rate during a sharp move sells names at
// the wrong price in whichever direction hurts — and the mitigation is
// keeping it fresh, not anything this code can do. Kept as one global so
// a future logic realm can swap in a real oracle without touching the
// vault or restating a single price.
func RateUgnotPerUsd() int64 {
	if v := nsdata.GetGlobal(keyRate); v != "" {
		if r, err := strconv.ParseInt(v, 10, 64); err == nil && r > 0 {
			return r
		}
	}
	return fallbackRate
}

// NamePrice converts the USD price to ugnot for settlement. Rounds UP,
// so rounding never sells a name below its listed price; a free name
// stays exactly free.
func NamePrice(domainLabel, label string) int64 {
	usd := NamePriceUSD(domainLabel, label)
	if usd <= 0 {
		return 0
	}
	rate := RateUgnotPerUsd()
	return (usd*rate + microUSD - 1) / microUSD
}

// -- rule plumbing --

func applyRule(v string, base int64) int64 {
	if strings.HasPrefix(v, "%") {
		pct, err := strconv.ParseInt(v[1:], 10, 64)
		if err != nil || pct < 0 {
			return base
		}
		return base * pct / 100
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil || n < 0 {
		return base
	}
	return n
}

func lookupRule(csv, want string) (string, bool) {
	if csv == "" {
		return "", false
	}
	for _, pair := range strings.Split(csv, ",") {
		parts := strings.SplitN(strings.TrimSpace(pair), ":", 2)
		if len(parts) != 2 {
			continue
		}
		if strings.TrimSpace(parts[0]) == want {
			return strings.TrimSpace(parts[1]), true
		}
	}
	return "", false
}

// normalizeRules validates and canonicalises a rule string before it is
// stored, so a malformed entry can never reach storage and poison every
// later lookup.
func normalizeRules(csv string, numericKeys bool) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad rule, want key:value — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" {
			panic("nslogic: empty rule key")
		}
		if numericKeys {
			if n, err := strconv.Atoi(k); err != nil || n <= 0 {
				panic("nslogic: length must be a positive number — got " + k)
			}
		} else if strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in rule — " + k)
		}
		if strings.HasPrefix(v, "%") {
			if p, err := strconv.ParseInt(v[1:], 10, 64); err != nil || p < 0 {
				panic("nslogic: bad percentage — " + v)
			}
		} else if n, err := strconv.ParseInt(v, 10, 64); err != nil || n < 0 {
			panic("nslogic: bad amount — " + v)
		}
		if seen[k] {
			panic("nslogic: duplicate rule key — " + k)
		}
		seen[k] = true
		out = append(out, k+":"+v)
		if len(out) > maxRules {
			panic("nslogic: too many rules (max 64)")
		}
	}
	return strings.Join(out, ",")
}

// Package nslogic is the swappable "business rules" half of the split
// (NOTES.md §9t). It holds every piece of policy that might reasonably
// change — pricing, character validation, payment/refund, freeze rules,
// transfer restrictions — and no persistent records of its own.
//
// Every mutation here ends by calling into nsdata's narrow Record/Raw
// API via cross(cur). nsdata trusts whichever address is currently wired
// up as trustedLogic to have done its own authorization checks
// correctly, so THIS realm is where "is the caller allowed to do this"
// actually lives. If a bug is found here, admin deploys a fixed nslogic
// and re-points nsdata.SetTrustedLogic at it — no data migration,
// records and config untouched.
//
// Deliberately reads config fresh from nsdata on every call rather than
// caching it. The one thing that cannot be read fresh is a COMPILED
// regex — avl trees store the pattern string, not the compiled object —
// so that one value is cached, and the cache is validated against
// nsdata on every use (see currentLabelRe).
package nslogic

import (
	"regexp"

	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

const (
	ugnot    = "ugnot"
	bpsDenom = 10_000
)

// Cached compile of nsdata's stored labelPattern. Both fields are
// written together and only by currentLabelRe.
var (
	labelPattern string
	reLabel      *regexp.Regexp
)

// Structural, not admin-tunable, so it stays a local constant: anything
// shaped like a real gno.land address is refused as a label, so a name
// can never be mistaken for a raw wallet address in a UI.
var reAddressLookalike = regexp.MustCompile(`^g1[a-z0-9]{20,38}$`)

// currentLabelRe returns the compiled form of whatever pattern nsdata
// currently stores, recompiling only when the string has changed.
//
// This replaces a snapshot taken once in init(). The snapshot was a
// silent-divergence bug: nsdata holds the pattern string, this realm
// held a compiled copy, and nothing kept them in sync across a
// logic-realm swap. A replacement nslogic deployed before the last
// SetLabelPattern would enforce its own stale pattern while every
// reader — GetLabelPattern, the error message, the UI — reported
// nsdata's newer one, so registrations would fail against a rule nobody
// could see. Reading through here on every call makes that impossible
// by construction.
func currentLabelRe() *regexp.Regexp {
	p := nsdata.GetLabelPattern()
	if reLabel == nil || p != labelPattern {
		compiled, err := regexp.Compile(p)
		if err != nil {
			panic("nslogic: stored label pattern does not compile: " + err.Error())
		}
		labelPattern, reLabel = p, compiled
	}
	return reLabel
}

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g17l06jwgez8aun250609y6ej4048e6d78zfle3s/nsdata"
)

// validateLabel — same policy as the original single-realm build (see
// NOTES.md for the ENS/Starname/r/sys/users research behind it). Length
// bounds and the character pattern are both read from nsdata, so they
// survive a swap of this realm.
//
// Call sites, and why: RegisterName/RegisterDomain only (both the
// first-ever mint AND reclaiming a past-grace slot — a reclaim is a
// genuine new mint with a new owner). RenewName/RenewDomain deliberately
// do NOT call this — an already-registered name must keep renewing under
// whatever pattern was in force when it was minted, even after the admin
// tightens the pattern later.
func validateLabel(label string) {
	minLen, maxLen := nsdata.GetLabelLength()
	if len(label) < minLen || len(label) > maxLen {
		panic(ufmt.Sprintf("nslogic: label must be %d-%d characters", minLen, maxLen))
	}
	// Structural invariant, enforced regardless of what the admin-tunable
	// pattern happens to allow: "*" is the separator in both the token ID
	// (label*domain) and nsdata's storage key (domain*label). A label or
	// domain containing one would make those encodings ambiguous and let
	// two different names collide onto a single record.
	if strings.Contains(label, "*") {
		panic("nslogic: label may not contain '*'")
	}
	if !currentLabelRe().MatchString(label) {
		panic("nslogic: label doesn't match the current allowed pattern (see nsdata.GetLabelPattern)")
	}
	if reAddressLookalike.MatchString(label) {
		panic("nslogic: label looks like a wallet address, not allowed")
	}
}

// Package roulette implements a custom 35-pocket Provably Fair roulette (0–34).
//
// Round flow:
//  1. StartRound(serverSeedHash) — admin commit
//  2. PlaceBet(betType, betValue, clientSeed) — player wager in ugnot (-send)
//  3. ResolveRound(serverSeed) — reveal; result =
//     BigEndian(sha256(serverSeed+clientSeed+nonce)[:8]) % 35
//
// Straight-up NUMBER wins pay ×35. Outside bets (RED/BLACK/EVEN/ODD/LOW/HIGH) pay ×2.
// If the result is 0, all outside bets lose.
package roulette

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"strconv"
	"strings"
)

const (
	denom         = "ugnot"
	wheelSize     = 35 // 0–34
	payoutNumber  = 35
	payoutOutside = 2
	maxHistory    = 20
	statusIdle    = "idle"
	statusOpen    = "open"
)

// Accepted bet types.
const (
	BetNumber = "NUMBER" // straight up (0–34), pays 35x
	BetRed    = "RED"
	BetBlack  = "BLACK"
	BetEven   = "EVEN"
	BetOdd    = "ODD"
	BetLow    = "LOW"  // 1–17
	BetHigh   = "HIGH" // 18–34
)

// Red pockets (17). Black pockets are the remaining 1–34. Zero is green.
var reds = map[int]bool{
	1: true, 3: true, 5: true, 7: true, 9: true, 12: true, 14: true, 16: true,
	18: true, 19: true, 21: true, 23: true, 25: true, 27: true, 30: true, 32: true, 34: true,
}

// Bet is a single wager for the open round.
type Bet struct {
	Player     address
	BetType    string
	BetValue   int // pocket number when NUMBER, otherwise 0
	ClientSeed string
	Amount     int64
	Nonce      int
}

// RoundRecord stores a resolved round for Render / audit.
type RoundRecord struct {
	RoundID        int
	ServerSeedHash string
	ServerSeed     string
	ClientSeed     string
	Nonce          int
	Result         int
	Player         address
	BetType        string
	BetValue       int
	BetAmount      int64
	Won            bool
	Payout         int64
}

var (
	admin          address
	bankroll       int64
	status         = statusIdle
	serverSeedHash string
	currentBet     *Bet
	roundID        int
	nonceCounter   int
	lastResult     = -1
	history        []RoundRecord
)

// ---------------------------------------------------------------------------
// Bankroll & admin
// ---------------------------------------------------------------------------

func DepositBankroll(cur realm) {
	requireUserCall(cur)
	caller := cur.Previous().Address()
	claimOrAssertAdmin(caller)
	bankroll += requireUgnotSend()
}

func WithdrawBankroll(cur realm, amount int64) {
	requireUserCall(cur)
	claimOrAssertAdmin(cur.Previous().Address())
	if amount <= 0 {
		panic("roulette: withdraw amount must be positive")
	}
	if amount > bankroll {
		panic("roulette: insufficient bankroll for withdrawal")
	}
	bankroll -= amount
	sendUgnot(cur, cur.Previous().Address(), amount)
}

// ---------------------------------------------------------------------------
// Commit–Reveal
// ---------------------------------------------------------------------------

func StartRound(cur realm, hash string) {
	claimOrAssertAdmin(cur.Previous().Address())
	if status == statusOpen {
		panic("roulette: a round is already open")
	}
	if hash == "" {
		panic("roulette: serverSeedHash is empty")
	}
	if currentBet != nil {
		panic("roulette: inconsistent state (bet already placed)")
	}
	roundID++
	serverSeedHash = strings.ToLower(hash)
	status = statusOpen
	currentBet = nil
}

// PlaceBet records a wager.
// betType: NUMBER | RED | BLACK | EVEN | ODD | LOW | HIGH
// betValue: 0–34 when NUMBER, otherwise 0.
func PlaceBet(cur realm, betType string, betValue int, clientSeed string) {
	requireUserCall(cur)
	if status != statusOpen {
		panic("roulette: no open round (call StartRound first)")
	}
	if currentBet != nil {
		panic("roulette: a bet is already placed for this round")
	}
	if clientSeed == "" {
		panic("roulette: clientSeed is empty")
	}

	bt := strings.ToUpper(strings.TrimSpace(betType))
	validateBet(bt, betValue)

	amount := requireUgnotSend()
	mult := payoutFor(bt)
	// Coverage: after crediting the stake, bankroll >= amount * mult
	if bankroll < amount*(mult-1) {
		panic("roulette: insufficient bankroll to cover potential payout")
	}

	bankroll += amount
	nonceCounter++
	currentBet = &Bet{
		Player:     cur.Previous().Address(),
		BetType:    bt,
		BetValue:   betValue,
		ClientSeed: clientSeed,
		Amount:     amount,
		Nonce:      nonceCounter,
	}
}

func ResolveRound(cur realm, serverSeed string) {
	claimOrAssertAdmin(cur.Previous().Address())
	if status != statusOpen {
		panic("roulette: no open round to resolve")
	}
	if currentBet == nil {
		panic("roulette: no bet to resolve")
	}
	if serverSeed == "" {
		panic("roulette: serverSeed is empty")
	}

	actualHash := hashHex(serverSeed)
	if actualHash != serverSeedHash {
		panic("roulette: serverSeed does not match commit (possible cheat attempt)")
	}

	bet := currentBet
	result := VerifyFairness(serverSeed, bet.ClientSeed, bet.Nonce)
	lastResult = result

	won := betWins(bet.BetType, bet.BetValue, result)
	payout := int64(0)
	if won {
		payout = bet.Amount * payoutFor(bet.BetType)
		if bankroll < payout {
			panic("roulette: insufficient bankroll to pay winnings")
		}
		bankroll -= payout
		sendUgnot(cur, bet.Player, payout)
	}

	history = append(history, RoundRecord{
		RoundID:        roundID,
		ServerSeedHash: serverSeedHash,
		ServerSeed:     serverSeed,
		ClientSeed:     bet.ClientSeed,
		Nonce:          bet.Nonce,
		Result:         result,
		Player:         bet.Player,
		BetType:        bet.BetType,
		BetValue:       bet.BetValue,
		BetAmount:      bet.Amount,
		Won:            won,
		Payout:         payout,
	})
	if len(history) > maxHistory {
		history = history[len(history)-maxHistory:]
	}

	currentBet = nil
	serverSeedHash = ""
	status = statusIdle
}

// VerifyFairness is pure: sha256(serverSeed+clientSeed+nonce) → BE uint64 % 35
func VerifyFairness(serverSeed, clientSeed string, nonce int) int {
	payload := serverSeed + clientSeed + strconv.Itoa(nonce)
	sum := sha256.Sum256([]byte(payload))
	n := binary.BigEndian.Uint64(sum[:8])
	return int(n % uint64(wheelSize))
}

// ---------------------------------------------------------------------------
// Getters
// ---------------------------------------------------------------------------

func GetAdmin() address         { return admin }
func GetBankroll() int64        { return bankroll }
func GetStatus() string         { return status }
func GetLastResult() int        { return lastResult }
func GetRoundID() int           { return roundID }
func GetServerSeedHash() string { return serverSeedHash }
func GetHistory() []RoundRecord { return history }
func IsRed(n int) bool          { return reds[n] }

// ---------------------------------------------------------------------------
// Render
// ---------------------------------------------------------------------------

func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# Roulette 35 — Provably Fair\n\n")
	b.WriteString("Custom wheel **0–34** (0 green, 17 red, 17 black).\n\n")

	b.WriteString("## Status\n\n")
	b.WriteString("- **State**: `" + status + "`\n")
	b.WriteString("- **Casino Bankroll**: `" + strconv.FormatInt(bankroll, 10) + denom + "`\n")
	b.WriteString("- **Round**: `" + strconv.Itoa(roundID) + "`\n")
	if lastResult >= 0 {
		b.WriteString("- **Last number**: `" + strconv.Itoa(lastResult) + "` (" + colorName(lastResult) + ")\n")
	}
	if status == statusOpen {
		b.WriteString("- **Commit**: `" + serverSeedHash + "`\n")
		if currentBet != nil {
			b.WriteString("- **Bet**: `" + currentBet.BetType)
			if currentBet.BetType == BetNumber {
				b.WriteString(" " + strconv.Itoa(currentBet.BetValue))
			}
			b.WriteString("` · `" + strconv.FormatInt(currentBet.Amount, 10) + denom +
				"` · nonce `" + strconv.Itoa(currentBet.Nonce) + "`\n")
		}
	}
	b.WriteString("\n## History\n\n")
	if len(history) == 0 {
		b.WriteString("_No rounds yet._\n\n")
	} else {
		for i := len(history) - 1; i >= 0; i-- {
			h := history[i]
			out := "LOSS"
			if h.Won {
				out = "WIN +" + strconv.FormatInt(h.Payout, 10) + denom
			}
			b.WriteString("- #" + strconv.Itoa(h.RoundID) + " → **" + strconv.Itoa(h.Result) +
				"** | " + h.BetType)
			if h.BetType == BetNumber {
				b.WriteString("(" + strconv.Itoa(h.BetValue) + ")")
			}
			b.WriteString(" " + strconv.FormatInt(h.BetAmount, 10) + denom + " | " + out + "\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Provably Fair\n\n")
	b.WriteString("The roll result is computed deterministically using SHA-256: ")
	b.WriteString("`sha256(serverSeed + clientSeed + nonce) % 35`. ")
	b.WriteString("You can independently verify that the outcome was not altered by the casino.\n\n")
	b.WriteString("Payouts: Straight Up (NUMBER) ×35 · RED/BLACK/EVEN/ODD/LOW/HIGH ×2 · ")
	b.WriteString("**0** loses all outside bets.\n")
	return b.String()
}

// ---------------------------------------------------------------------------
// Settlement logic
// ---------------------------------------------------------------------------

func validateBet(bt string, betValue int) {
	switch bt {
	case BetNumber:
		if betValue < 0 || betValue >= wheelSize {
			panic("roulette: betValue must be between 0 and 34 for NUMBER")
		}
	case BetRed, BetBlack, BetEven, BetOdd, BetLow, BetHigh:
		if betValue != 0 {
			panic("roulette: betValue must be 0 for outside bets")
		}
	default:
		panic("roulette: invalid bet type (NUMBER|RED|BLACK|EVEN|ODD|LOW|HIGH)")
	}
}

func payoutFor(bt string) int64 {
	if bt == BetNumber {
		return payoutNumber
	}
	return payoutOutside
}

// betWins — zero loses every outside bet; NUMBER(0) can still win.
func betWins(bt string, betValue, result int) bool {
	switch bt {
	case BetNumber:
		return betValue == result
	case BetRed:
		return result != 0 && reds[result]
	case BetBlack:
		return result != 0 && !reds[result]
	case BetEven:
		return result != 0 && result%2 == 0
	case BetOdd:
		return result != 0 && result%2 == 1
	case BetLow:
		return result >= 1 && result <= 17
	case BetHigh:
		return result >= 18 && result <= 34
	default:
		return false
	}
}

func colorName(n int) string {
	if n == 0 {
		return "green"
	}
	if reds[n] {
		return "red"
	}
	return "black"
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func claimOrAssertAdmin(caller address) {
	if admin == "" {
		admin = caller
		return
	}
	if caller != admin {
		panic("roulette: only admin can perform this action")
	}
}

func requireUserCall(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("roulette: only user-call (maketx call) is accepted")
	}
}

func requireUgnotSend() int64 {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("roulette: send ugnot only via -send")
	}
	if sent[0].Amount <= 0 {
		panic("roulette: bet amount must be positive")
	}
	return sent[0].Amount
}

func sendUgnot(cur realm, to address, amount int64) {
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(denom, amount)))
}

func hashHex(seed string) string {
	sum := sha256.Sum256([]byte(seed))
	return hex.EncodeToString(sum[:])
}

package roulette

import (
	"chain"
	"chain/banker"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var rouletteAddr = chain.PackageAddress("gno.land/r/roulette")

func resetState() {
	admin = ""
	bankroll = 0
	status = statusIdle
	serverSeedHash = ""
	currentBet = nil
	roundID = 0
	nonceCounter = 0
	lastResult = -1
	history = nil
}

func seedHash(serverSeed string) string {
	sum := sha256.Sum256([]byte(serverSeed))
	return hex.EncodeToString(sum[:])
}

func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoins(addr).AmountOf(denom)
}

// TestVerifyFairness_Modulo35 — deterministic and in [0, 34].
func TestVerifyFairness_Modulo35(t *testing.T) {
	a := VerifyFairness("server-secret", "client-seed", 1)
	b := VerifyFairness("server-secret", "client-seed", 1)
	if a != b {
		t.Fatalf("non-deterministic: %d != %d", a, b)
	}
	if a < 0 || a > 34 {
		t.Fatalf("out of range [0,34]: %d", a)
	}
	for i := 0; i < 40; i++ {
		r := VerifyFairness("s", "c", i)
		if r < 0 || r >= wheelSize {
			t.Fatalf("out of range nonce=%d: %d", i, r)
		}
	}
}

// TestNumberPayout_x35 — winning NUMBER bet pays ×35.
func TestNumberPayout_x35(cur realm, t *testing.T) {
	defer resetState()

	adminAddr := testutils.TestAddress("admin")
	playerAddr := testutils.TestAddress("player")
	const (
		serverSeed = "number-win-seed"
		clientSeed = "player-seed"
		betAmount  = int64(100)
		depositAmt = int64(1_000_000)
	)

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: depositAmt}})
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: depositAmt}})
	DepositBankroll(cross(cur))
	StartRound(cross(cur), seedHash(serverSeed))

	nonce := nonceCounter + 1
	winNum := VerifyFairness(serverSeed, clientSeed, nonce)

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: betAmount}})
	testing.SetRealm(testing.NewUserRealm(playerAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: betAmount}})
	PlaceBet(cross(cur), BetNumber, winNum, clientSeed)

	before := balanceOf(playerAddr)
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	ResolveRound(cross(cur), serverSeed)

	payout := betAmount * payoutNumber
	uassert.Equal(t, winNum, GetLastResult())
	uassert.True(t, GetHistory()[0].Won)
	uassert.Equal(t, payout, GetHistory()[0].Payout)
	if balanceOf(playerAddr)-before != payout {
		t.Fatalf("payout: got %d want %d", balanceOf(playerAddr)-before, payout)
	}
	uassert.Equal(t, depositAmt+betAmount-payout, GetBankroll())
}

// TestColorPayout_x2 — winning RED bet pays ×2.
func TestColorPayout_x2(cur realm, t *testing.T) {
	defer resetState()

	adminAddr := testutils.TestAddress("admin2")
	playerAddr := testutils.TestAddress("player2")
	const (
		serverSeed = "color-win-seed"
		betAmount  = int64(200)
		depositAmt = int64(100_000)
	)

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: depositAmt}})
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: depositAmt}})
	DepositBankroll(cross(cur))
	StartRound(cross(cur), seedHash(serverSeed))

	var cs string
	var res int
	found := false
	for i := 0; i < 200; i++ {
		cs = "red-try-" + strconv.Itoa(i)
		res = VerifyFairness(serverSeed, cs, nonceCounter+1)
		if res != 0 && IsRed(res) {
			found = true
			break
		}
	}
	if !found {
		t.Fatal("could not find a red outcome for the test")
	}

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: betAmount}})
	testing.SetRealm(testing.NewUserRealm(playerAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: betAmount}})
	PlaceBet(cross(cur), BetRed, 0, cs)

	before := balanceOf(playerAddr)
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	ResolveRound(cross(cur), serverSeed)

	payout := betAmount * payoutOutside
	uassert.Equal(t, res, GetLastResult())
	uassert.True(t, GetHistory()[0].Won)
	uassert.Equal(t, payout, GetHistory()[0].Payout)
	if balanceOf(playerAddr)-before != payout {
		t.Fatalf("color payout: got %d want %d", balanceOf(playerAddr)-before, payout)
	}
}

// TestOutsideLosesOnZero — result 0 ⇒ BLACK bet loses.
func TestOutsideLosesOnZero(cur realm, t *testing.T) {
	defer resetState()

	adminAddr := testutils.TestAddress("admin3")
	playerAddr := testutils.TestAddress("player3")
	const depositAmt = int64(50_000)
	const betAmount = int64(50)

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: depositAmt}})
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: depositAmt}})
	DepositBankroll(cross(cur))
	StartRound(cross(cur), seedHash("zero-seed-hunt"))

	var cs string
	found := false
	for i := 0; i < 500; i++ {
		cs = "z-" + strconv.Itoa(i)
		if VerifyFairness("zero-seed-hunt", cs, nonceCounter+1) == 0 {
			found = true
			break
		}
	}
	if !found {
		t.Fatal("could not find a zero outcome for the test")
	}

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: betAmount}})
	testing.SetRealm(testing.NewUserRealm(playerAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: betAmount}})
	PlaceBet(cross(cur), BetBlack, 0, cs)

	bankBefore := GetBankroll()
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	ResolveRound(cross(cur), "zero-seed-hunt")

	uassert.Equal(t, 0, GetLastResult())
	uassert.False(t, GetHistory()[0].Won)
	uassert.Equal(t, bankBefore, GetBankroll())
}

// TestCheat_BadServerSeed — bad reveal → abort.
func TestCheat_BadServerSeed(cur realm, t *testing.T) {
	defer resetState()

	adminAddr := testutils.TestAddress("admin4")
	playerAddr := testutils.TestAddress("player4")
	const depositAmt = int64(100_000)
	const betAmount = int64(10)

	testing.IssueCoins(rouletteAddr, chain.Coins{{Denom: denom, Amount: depositAmt + betAmount}})
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: depositAmt}})
	DepositBankroll(cross(cur))
	StartRound(cross(cur), seedHash("vrai-secret"))

	testing.SetRealm(testing.NewUserRealm(playerAddr))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: betAmount}})
	PlaceBet(cross(cur), BetNumber, 7, "client")

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	uassert.AbortsContains(t, cur, "serverSeed does not match commit", func() {
		ResolveRound(cross(cur), "faux-secret")
	})
	uassert.Equal(t, statusOpen, GetStatus())
}

// TestBetWinsHelpers — color / even-odd / low-high coverage.
func TestBetWinsHelpers(t *testing.T) {
	if !betWins(BetNumber, 0, 0) {
		t.Fatal("NUMBER(0) must win on 0")
	}
	if betWins(BetRed, 0, 0) || betWins(BetBlack, 0, 0) || betWins(BetEven, 0, 0) {
		t.Fatal("outside bets must lose on 0")
	}
	if !betWins(BetRed, 0, 1) || betWins(BetBlack, 0, 1) {
		t.Fatal("1 is red")
	}
	if !betWins(BetBlack, 0, 2) || betWins(BetRed, 0, 2) {
		t.Fatal("2 is black")
	}
	if !betWins(BetEven, 0, 2) || !betWins(BetOdd, 0, 3) {
		t.Fatal("EVEN/ODD")
	}
	if !betWins(BetLow, 0, 17) || betWins(BetLow, 0, 18) {
		t.Fatal("LOW 1-17")
	}
	if !betWins(BetHigh, 0, 18) || betWins(BetHigh, 0, 17) {
		t.Fatal("HIGH 18-34")
	}
}
